import { jsonSchema, tool } from 'ai';

/**
 * Input type for Hello World Tool
 */
type HelloWorldInput = {
  includeTimestamp?: boolean;
};

/**
 * Hello World Tool
 * Returns a simple "Hello, World!" greeting
 *
 * This is a proper AI SDK v6 tool that can be used with streamText()
 * Uses jsonSchema() to avoid Zod 4 JSON Schema conversion issues with OpenAI
 */
export const helloWorldTool = tool({
  description: 'Returns a simple "Hello, World!" greeting message',
  inputSchema: jsonSchema<HelloWorldInput>({
    type: 'object',
    properties: {
      includeTimestamp: {
        type: 'boolean',
        description: 'Whether to include a timestamp in the response',
      },
    },
    additionalProperties: false,
  }),
  async execute({ includeTimestamp = true }) {
    const response: Record<string, unknown> = {
      message: 'Hello, World!',
    };

    if (includeTimestamp) {
      response.timestamp = new Date().toISOString();
    }

    return response;
  },
});

/**
 * Input type for Hello Name Tool
 */
type HelloNameInput = {
  name: string;
};

/**
 * Hello Name Tool
 * Returns a personalized greeting with the provided name
 *
 * This is a proper AI SDK v6 tool that can be used with streamText()
 * Uses jsonSchema() to avoid Zod 4 JSON Schema conversion issues with OpenAI
 */
export const helloNameTool = tool({
  description: 'Returns a personalized greeting with the provided name',
  inputSchema: jsonSchema<HelloNameInput>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description: 'The name of the person to greet',
      },
    },
    required: ['name'],
    additionalProperties: false,
  }),
  async execute({ name }) {
    return {
      message: `Hello, ${name}!`,
      timestamp: new Date().toISOString(),
    };
  },
});

{
  "name": "@tpmjs/hello",
  "version": "0.0.3",
  "description": "Example TPMJS tools - Hello World and Hello Name",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "clean": "rm -rf dist",
    "type-check": "tsc --noEmit --incremental --tsBuildInfoFile tsconfig.tsbuildinfo"
  },
  "keywords": [
    "tpmjs",
    "ai-sdk",
    "hello",
    "example"
  ],
  "tpmjs": {
    "category": "text-analysis",
    "frameworks": [
      "vercel-ai"
    ],
    "tools": [
      {
        "name": "helloWorldTool",
        "description": "Returns a simple 'Hello, World!' greeting with optional timestamp and customizable message",
        "parameters": [
          {
            "name": "includeTimestamp",
            "type": "boolean",
            "description": "Whether to include the current timestamp in the greeting",
            "required": false
          }
        ],
        "returns": {
          "type": "string",
          "description": "A greeting message, optionally with timestamp"
        }
      },
      {
        "name": "helloNameTool",
        "description": "Returns a personalized greeting with the provided name",
        "parameters": [
          {
            "name": "name",
            "type": "string",
            "description": "The name to greet",
            "required": true
          },
          {
            "name": "formal",
            "type": "boolean",
            "description": "Whether to use formal greeting (Mr./Ms.)",
            "required": false
          }
        ],
        "returns": {
          "type": "string",
          "description": "A personalized greeting message"
        }
      }
    ]
  },
  "dependencies": {
    "ai": "6.0.49"
  },
  "devDependencies": {
    "@tpmjs/tsconfig": "workspace:*",
    "tsx": "^4.21.0",
    "typescript": "^5.9.3"
  },
  "files": [
    "dist",
    "README.md"
  ]
}

