  1→/**
  2→ * Type-safe API client for integration tests
  3→ *
  4→ * Provides convenient methods for making API requests
  5→ * with proper error handling and response parsing.
  6→ */
  7→
  8→import { collectSSEEvents, type SSEEvent } from './sse-parser';
  9→
 10→export interface ApiResponse<T = unknown> {
 11→  ok: boolean;
 12→  status: number;
 13→  data: T;
 14→  headers: Headers;
 15→}
 16→
 17→export interface ApiErrorResponse {
 18→  ok: false;
 19→  status: number;
 20→  error: string;
 21→  headers: Headers;
 22→}
 23→
 24→export type ApiResult<T> = ApiResponse<T> | ApiErrorResponse;
 25→
 26→/**
 27→ * Create an API client with a base URL and optional custom fetch
 28→ */
 29→export function createApiClient(baseUrl: string, customFetch: typeof fetch = fetch) {
 30→  const normalizedBaseUrl = baseUrl.replace(/\/$/, '');
 31→
 32→  async function request<T = unknown>(
 33→    method: string,
 34→    path: string,
 35→    options: {
 36→      body?: unknown;
 37→      headers?: Record<string, string>;
 38→      query?: Record<string, string | number | boolean | undefined>;
 39→    } = {}
 40→  ): Promise<ApiResult<T>> {
 41→    const { body, headers = {}, query } = options;
 42→
 43→    let url = `${normalizedBaseUrl}${path}`;
 44→
 45→    // Add query parameters
 46→    if (query) {
 47→      const params = new URLSearchParams();
 48→      for (const [key, value] of Object.entries(query)) {
 49→        if (value !== undefined) {
 50→          params.set(key, String(value));
 51→        }
 52→      }
 53→      const queryString = params.toString();
 54→      if (queryString) {
 55→        url += `?${queryString}`;
 56→      }
 57→    }
 58→
 59→    const requestHeaders: Record<string, string> = {
 60→      ...headers,
 61→    };
 62→
 63→    if (body !== undefined) {
 64→      requestHeaders['Content-Type'] = 'application/json';
 65→    }
 66→
 67→    const response = await customFetch(url, {
 68→      method,
 69→      headers: requestHeaders,
 70→      body: body !== undefined ? JSON.stringify(body) : undefined,
 71→    });
 72→
 73→    if (!response.ok) {
 74→      let errorMessage = `HTTP ${response.status}`;
 75→      try {
 76→        const errorData = await response.json();
 77→        errorMessage = errorData.error || errorData.message || errorMessage;
 78→      } catch {
 79→        // Use default error message
 80→      }
 81→
 82→      return {
 83→        ok: false,
 84→        status: response.status,
 85→        error: errorMessage,
 86→        headers: response.headers,
 87→      };
 88→    }
 89→
 90→    let data: T;
 91→    const contentType = response.headers.get('content-type');
 92→
 93→    if (contentType?.includes('application/json')) {
 94→      data = await response.json();
 95→    } else {
 96→      data = (await response.text()) as unknown as T;
 97→    }
 98→
 99→    return {
100→      ok: true,
101→      status: response.status,
102→      data,
103→      headers: response.headers,
104→    };
105→  }
106→
107→  return {
108→    /**
109→     * Make a GET request
110→     */
111→    get<T = unknown>(
112→      path: string,
113→      options?: {
114→        headers?: Record<string, string>;
115→        query?: Record<string, string | number | boolean | undefined>;
116→      }
117→    ): Promise<ApiResult<T>> {
118→      return request<T>('GET', path, options);
119→    },
120→
121→    /**
122→     * Make a POST request
123→     */
124→    post<T = unknown>(
125→      path: string,
126→      body?: unknown,
127→      options?: {
128→        headers?: Record<string, string>;
129→        query?: Record<string, string | number | boolean | undefined>;
130→      }
131→    ): Promise<ApiResult<T>> {
132→      return request<T>('POST', path, { ...options, body });
133→    },
134→
135→    /**
136→     * Make a PATCH request
137→     */
138→    patch<T = unknown>(
139→      path: string,
140→      body?: unknown,
141→      options?: {
142→        headers?: Record<string, string>;
143→        query?: Record<string, string | number | boolean | undefined>;
144→      }
145→    ): Promise<ApiResult<T>> {
146→      return request<T>('PATCH', path, { ...options, body });
147→    },
148→
149→    /**
150→     * Make a PUT request
151→     */
152→    put<T = unknown>(
153→      path: string,
154→      body?: unknown,
155→      options?: {
156→        headers?: Record<string, string>;
157→        query?: Record<string, string | number | boolean | undefined>;
158→      }
159→    ): Promise<ApiResult<T>> {
160→      return request<T>('PUT', path, { ...options, body });
161→    },
162→
163→    /**
164→     * Make a DELETE request
165→     */
166→    delete<T = unknown>(
167→      path: string,
168→      options?: {
169→        headers?: Record<string, string>;
170→        query?: Record<string, string | number | boolean | undefined>;
171→      }
172→    ): Promise<ApiResult<T>> {
173→      return request<T>('DELETE', path, options);
174→    },
175→
176→    /**
177→     * Make a request to an SSE endpoint and collect events
178→     */
179→    async sse(
180→      path: string,
181→      body?: unknown,
182→      options?: {
183→        headers?: Record<string, string>;
184→        timeout?: number;
185→        maxEvents?: number;
186→      }
187→    ): Promise<{ ok: boolean; status: number; events: SSEEvent[] }> {
188→      const { headers = {}, timeout, maxEvents } = options || {};
189→
190→      const url = `${normalizedBaseUrl}${path}`;
191→      const requestHeaders: Record<string, string> = {
192→        ...headers,
193→      };
194→
195→      if (body !== undefined) {
196→        requestHeaders['Content-Type'] = 'application/json';
197→      }
198→
199→      const response = await customFetch(url, {
200→        method: body !== undefined ? 'POST' : 'GET',
201→        headers: requestHeaders,
202→        body: body !== undefined ? JSON.stringify(body) : undefined,
203→      });
204→
205→      if (!response.ok) {
206→        return {
207→          ok: false,
208→          status: response.status,
209→          events: [],
210→        };
211→      }
212→
213→      const events = await collectSSEEvents(response, { timeout, maxEvents });
214→
215→      return {
216→        ok: true,
217→        status: response.status,
218→        events,
219→      };
220→    },
221→
222→    /**
223→     * Make a raw request and return the Response object
224→     */
225→    async raw(
226→      method: string,
227→      path: string,
228→      options?: {
229→        body?: unknown;
230→        headers?: Record<string, string>;
231→      }
232→    ): Promise<Response> {
233→      const { body, headers = {} } = options || {};
234→
235→      const url = `${normalizedBaseUrl}${path}`;
236→      const requestHeaders: Record<string, string> = {
237→        ...headers,
238→      };
239→
240→      if (body !== undefined) {
241→        requestHeaders['Content-Type'] = 'application/json';
242→      }
243→
244→      return customFetch(url, {
245→        method,
246→        headers: requestHeaders,
247→        body: body !== undefined ? JSON.stringify(body) : undefined,
248→      });
249→    },
250→  };
251→}
252→
253→export type ApiClient = ReturnType<typeof createApiClient>;
254→

  1→/**
  2→ * Agent factory for integration tests
  3→ *
  4→ * Creates test agents with auto-generated test prefixes
  5→ * and tracks them for cleanup.
  6→ */
  7→
  8→import type { ApiClient } from '../api-client';
  9→import type { TestDataTracker } from '../cleanup';
 10→
 11→export interface CreateAgentOptions {
 12→  uid?: string;
 13→  name?: string;
 14→  description?: string;
 15→  provider?: 'OPENAI' | 'ANTHROPIC' | 'GOOGLE' | 'GROQ' | 'MISTRAL';
 16→  modelId?: string;
 17→  systemPrompt?: string;
 18→  temperature?: number;
 19→  maxToolCallsPerTurn?: number;
 20→  maxMessagesInContext?: number;
 21→  isPublic?: boolean;
 22→  toolIds?: string[];
 23→  collectionIds?: string[];
 24→}
 25→
 26→export interface AgentFactoryResult {
 27→  id: string;
 28→  uid: string;
 29→  name: string;
 30→  description: string | null;
 31→  provider: string;
 32→  modelId: string;
 33→  isPublic: boolean;
 34→}
 35→
 36→/**
 37→ * Create an agent factory bound to a specific API client and tracker
 38→ */
 39→export function createAgentFactory(api: ApiClient, tracker: TestDataTracker) {
 40→  let counter = 0;
 41→
 42→  return {
 43→    /**
 44→     * Create a new test agent
 45→     */
 46→    async create(options: CreateAgentOptions = {}): Promise<AgentFactoryResult> {
 47→      counter++;
 48→      const timestamp = Date.now();
 49→
 50→      const uid = options.uid || `test-agent-${timestamp}-${counter}`;
 51→      const name = options.name || `Test Agent ${timestamp}-${counter}`;
 52→
 53→      const result = await api.post<{ success: boolean; data: AgentFactoryResult }>('/api/agents', {
 54→        uid,
 55→        name,
 56→        description: options.description ?? 'Integration test agent',
 57→        provider: options.provider ?? 'OPENAI',
 58→        modelId: options.modelId ?? 'gpt-4o-mini',
 59→        systemPrompt: options.systemPrompt ?? 'You are a helpful test agent.',
 60→        temperature: options.temperature ?? 0.7,
 61→        maxToolCallsPerTurn: options.maxToolCallsPerTurn ?? 5,
 62→        maxMessagesInContext: options.maxMessagesInContext ?? 10,
 63→        isPublic: options.isPublic ?? true,
 64→      });
 65→
 66→      if (!result.ok) {
 67→        const errorResult = result as { error: string; status: number };
 68→        throw new Error(
 69→          `Failed to create agent: ${errorResult.error} (status: ${errorResult.status})`
 70→        );
 71→      }
 72→
 73→      const agent = result.data.data;
 74→      tracker.trackAgent(agent.id);
 75→
 76→      // Add tools if specified
 77→      if (options.toolIds && options.toolIds.length > 0) {
 78→        for (const toolId of options.toolIds) {
 79→          await api.post(`/api/agents/${agent.id}/tools`, { toolId });
 80→        }
 81→      }
 82→
 83→      // Add collections if specified
 84→      if (options.collectionIds && options.collectionIds.length > 0) {
 85→        for (const collectionId of options.collectionIds) {
 86→          await api.post(`/api/agents/${agent.id}/collections`, { collectionId });
 87→        }
 88→      }
 89→
 90→      return agent;
 91→    },
 92→
 93→    /**
 94→     * Create multiple test agents
 95→     */
 96→    async createMany(
 97→      count: number,
 98→      options: CreateAgentOptions = {}
 99→    ): Promise<AgentFactoryResult[]> {
100→      const agents: AgentFactoryResult[] = [];
101→      for (let i = 0; i < count; i++) {
102→        const agent = await this.create({
103→          ...options,
104→          uid: options.uid ? `${options.uid}-${i}` : undefined,
105→          name: options.name ? `${options.name} ${i}` : undefined,
106→        });
107→        agents.push(agent);
108→      }
109→      return agents;
110→    },
111→
112→    /**
113→     * Get an agent by ID
114→     */
115→    async get(id: string): Promise<AgentFactoryResult | null> {
116→      const result = await api.get<{ success: boolean; data: AgentFactoryResult }>(
117→        `/api/agents/${id}`
118→      );
119→      if (!result.ok) {
120→        return null;
121→      }
122→      return result.data.data;
123→    },
124→
125→    /**
126→     * Update an agent
127→     */
128→    async update(id: string, updates: Partial<CreateAgentOptions>): Promise<AgentFactoryResult> {
129→      const result = await api.patch<{ success: boolean; data: AgentFactoryResult }>(
130→        `/api/agents/${id}`,
131→        updates
132→      );
133→      if (!result.ok) {
134→        throw new Error(`Failed to update agent: ${(result as { error: string }).error}`);
135→      }
136→      return result.data.data;
137→    },
138→
139→    /**
140→     * Delete an agent
141→     */
142→    async delete(id: string): Promise<void> {
143→      const result = await api.delete(`/api/agents/${id}`);
144→      if (!result.ok) {
145→        throw new Error(`Failed to delete agent: ${(result as { error: string }).error}`);
146→      }
147→    },
148→  };
149→}
150→
151→export type AgentFactory = ReturnType<typeof createAgentFactory>;
