  1→/**
  2→ * TPMJS Agent Sandbox Server (Deno)
  3→ *
  4→ * Stateful execution server with session-scoped filesystem persistence.
  5→ * Based on the Railway executor but adds session management so files
  6→ * created by one tool call persist for subsequent calls within the same conversation.
  7→ */
  8→
  9→// Import zod-to-json-schema for Zod v3 support
 10→import { zodToJsonSchema } from 'https://esm.sh/zod-to-json-schema@3.25.0';
 11→
 12→// ─── Crash Protection ───────────────────────────────────────────────────────
 13→globalThis.addEventListener('unhandledrejection', (event) => {
 14→  event.preventDefault();
 15→  console.error('⚠️  Unhandled promise rejection (caught, process continues):', event.reason);
 16→});
 17→
 18→globalThis.addEventListener('error', (event) => {
 19→  console.error('⚠️  Uncaught error (caught, process continues):', event.error || event.message);
 20→  event.preventDefault();
 21→});
 22→
 23→// ─── Configuration ──────────────────────────────────────────────────────────
 24→const PORT = Number(Deno.env.get('PORT') || '3002');
 25→const EXECUTOR_API_KEY = Deno.env.get('EXECUTOR_API_KEY');
 26→const MAX_CONCURRENT_SESSIONS = Number(Deno.env.get('MAX_CONCURRENT_SESSIONS') || '50');
 27→const DEFAULT_SESSION_TTL_SECONDS = Number(Deno.env.get('DEFAULT_SESSION_TTL_SECONDS') || '3600');
 28→const SESSION_DISK_QUOTA_MB = Number(Deno.env.get('SESSION_DISK_QUOTA_MB') || '100');
 29→const SESSIONS_BASE_DIR = '/tmp/tpmjs-sandbox/sessions';
 30→
 31→// Module cache
 32→const CACHE_TTL_MS = 2 * 60 * 1000;
 33→const MAX_CACHE_SIZE = 200;
 34→
 35→interface CacheEntry {
 36→  // biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic
 37→  module: any;
 38→  expiresAt: number;
 39→  isFactory: boolean;
 40→}
 41→
 42→const moduleCache = new Map<string, CacheEntry>();
 43→
 44→// ─── Session Management ─────────────────────────────────────────────────────
 45→
 46→interface Session {
 47→  sessionId: string;
 48→  workDir: string;
 49→  createdAt: Date;
 50→  expiresAt: Date;
 51→  toolCallCount: number;
 52→}
 53→
 54→const sessions = new Map<string, Session>();
 55→
 56→function getSessionWorkDir(sessionId: string): string {
 57→  // Sanitize sessionId to be filesystem-safe
 58→  const safe = sessionId.replace(/[^a-zA-Z0-9_:-]/g, '_');
 59→  return `${SESSIONS_BASE_DIR}/${safe}/workspace`;
 60→}
 61→
 62→async function createSession(
 63→  sessionId: string,
 64→  timeoutSeconds?: number
 65→): Promise<Session & { resumed: boolean }> {
 66→  const ttl = timeoutSeconds ?? DEFAULT_SESSION_TTL_SECONDS;
 67→
 68→  // Idempotent: if session exists, extend TTL and return it
 69→  const existing = sessions.get(sessionId);
 70→  if (existing) {
 71→    existing.expiresAt = new Date(Date.now() + ttl * 1000);
 72→    console.log(`🔄 Session resumed: ${sessionId} (TTL extended to ${ttl}s)`);
 73→    return { ...existing, resumed: true };
 74→  }
 75→
 76→  // Check concurrent session limit
 77→  if (sessions.size >= MAX_CONCURRENT_SESSIONS) {
 78→    throw new Error(
 79→      `Maximum concurrent sessions reached (${MAX_CONCURRENT_SESSIONS}). Try again later.`
 80→    );
 81→  }
 82→
 83→  const workDir = getSessionWorkDir(sessionId);
 84→
 85→  // Create workspace directory
 86→  await Deno.mkdir(workDir, { recursive: true });
 87→
 88→  const session: Session = {
 89→    sessionId,
 90→    workDir,
 91→    createdAt: new Date(),
 92→    expiresAt: new Date(Date.now() + ttl * 1000),
 93→    toolCallCount: 0,
 94→  };
 95→
 96→  sessions.set(sessionId, session);
 97→  console.log(`✅ Session created: ${sessionId} (TTL: ${ttl}s, workDir: ${workDir})`);
 98→
 99→  return { ...session, resumed: false };
100→}
101→
102→async function destroySession(sessionId: string): Promise<boolean> {
103→  const session = sessions.get(sessionId);
104→  if (!session) {
105→    return false;
106→  }
107→
108→  sessions.delete(sessionId);
109→
110→  // Clean up workspace directory
111→  try {
112→    await Deno.remove(session.workDir, { recursive: true });
113→    // Also remove parent directory (the sessionId dir)
114→    const parentDir = session.workDir.replace(/\/workspace$/, '');
115→    await Deno.remove(parentDir, { recursive: true }).catch(() => {});
116→  } catch {
117→    // Directory may already be cleaned up
118→  }
119→
120→  console.log(`🗑️  Session destroyed: ${sessionId}`);
121→  return true;
122→}
123→
124→function getSession(sessionId: string): Session | null {
125→  const session = sessions.get(sessionId);
126→  if (!session) return null;
127→
128→  // Check if expired
129→  if (new Date() > session.expiresAt) {
130→    // Mark for cleanup but don't block
131→    destroySession(sessionId).catch(() => {});
132→    return null;
133→  }
134→
135→  return session;
136→}
137→
138→// ─── Session Cleanup ────────────────────────────────────────────────────────
139→
140→async function cleanupExpiredSessions(): Promise<void> {
141→  const now = new Date();
142→  let cleaned = 0;
143→
144→  for (const [sessionId, session] of sessions.entries()) {
145→    if (now > session.expiresAt) {
146→      await destroySession(sessionId).catch(() => {});
147→      cleaned++;
148→    }
149→  }
150→

  1→/**
  2→ * Collection factory for integration tests
  3→ *
  4→ * Creates test collections with auto-generated test prefixes
  5→ * and tracks them for cleanup.
  6→ */
  7→
  8→import type { ApiClient } from '../api-client';
  9→import type { TestDataTracker } from '../cleanup';
 10→
 11→export interface CreateCollectionOptions {
 12→  slug?: string;
 13→  name?: string;
 14→  description?: string;
 15→  isPublic?: boolean;
 16→  toolIds?: string[];
 17→}
 18→
 19→export interface CollectionFactoryResult {
 20→  id: string;
 21→  slug: string;
 22→  name: string;
 23→  description: string | null;
 24→  isPublic: boolean;
 25→  toolCount?: number;
 26→}
 27→
 28→/**
 29→ * Create a collection factory bound to a specific API client and tracker
 30→ */
 31→export function createCollectionFactory(api: ApiClient, tracker: TestDataTracker) {
 32→  let counter = 0;
 33→
 34→  return {
 35→    /**
 36→     * Create a new test collection
 37→     */
 38→    async create(options: CreateCollectionOptions = {}): Promise<CollectionFactoryResult> {
 39→      counter++;
 40→      const timestamp = Date.now();
 41→
 42→      const slug = options.slug || `test-collection-${timestamp}-${counter}`;
 43→      const name = options.name || `Test Collection ${timestamp}-${counter}`;
 44→
 45→      const result = await api.post<{ success: boolean; data: CollectionFactoryResult }>(
 46→        '/api/collections',
 47→        {
 48→          slug,
 49→          name,
 50→          description: options.description ?? 'Integration test collection',
 51→          isPublic: options.isPublic ?? true,
 52→        }
 53→      );
 54→
 55→      if (!result.ok) {
 56→        const errorResult = result as { error: string; status: number };
 57→        throw new Error(
 58→          `Failed to create collection: ${errorResult.error} (status: ${errorResult.status})`
 59→        );
 60→      }
 61→
 62→      const collection = result.data.data;
 63→      tracker.trackCollection(collection.id);
 64→
 65→      // Add tools if specified
 66→      if (options.toolIds && options.toolIds.length > 0) {
 67→        for (const toolId of options.toolIds) {
 68→          await api.post(`/api/collections/${collection.id}/tools`, { toolId });
 69→        }
 70→      }
 71→
 72→      return collection;
 73→    },
 74→
 75→    /**
 76→     * Create multiple test collections
 77→     */
 78→    async createMany(
 79→      count: number,
 80→      options: CreateCollectionOptions = {}
 81→    ): Promise<CollectionFactoryResult[]> {
 82→      const collections: CollectionFactoryResult[] = [];
 83→      for (let i = 0; i < count; i++) {
 84→        const collection = await this.create({
 85→          ...options,
 86→          slug: options.slug ? `${options.slug}-${i}` : undefined,
 87→          name: options.name ? `${options.name} ${i}` : undefined,
 88→        });
 89→        collections.push(collection);
 90→      }
 91→      return collections;
 92→    },
 93→
 94→    /**
 95→     * Get a collection by ID
 96→     */
 97→    async get(id: string): Promise<CollectionFactoryResult | null> {
 98→      const result = await api.get<{ success: boolean; data: CollectionFactoryResult }>(
 99→        `/api/collections/${id}`
100→      );
101→      if (!result.ok) {
102→        return null;
103→      }
104→      return result.data.data;
105→    },
106→
107→    /**
108→     * Update a collection
109→     */
110→    async update(
111→      id: string,
112→      updates: Partial<CreateCollectionOptions>
113→    ): Promise<CollectionFactoryResult> {
114→      const result = await api.patch<{ success: boolean; data: CollectionFactoryResult }>(
115→        `/api/collections/${id}`,
116→        updates
117→      );
118→      if (!result.ok) {
119→        throw new Error(`Failed to update collection: ${(result as { error: string }).error}`);
120→      }
121→      return result.data.data;
122→    },
123→
124→    /**
125→     * Delete a collection
126→     */
127→    async delete(id: string): Promise<void> {
128→      const result = await api.delete(`/api/collections/${id}`);
129→      if (!result.ok) {
130→        throw new Error(`Failed to delete collection: ${(result as { error: string }).error}`);
131→      }
132→    },
133→
134→    /**
135→     * Add a tool to a collection
136→     */
137→    async addTool(collectionId: string, toolId: string): Promise<void> {
138→      const result = await api.post(`/api/collections/${collectionId}/tools`, { toolId });
139→      if (!result.ok) {
140→        throw new Error(`Failed to add tool to collection: ${(result as { error: string }).error}`);
141→      }
142→    },
143→
144→    /**
145→     * Remove a tool from a collection
146→     */
147→    async removeTool(collectionId: string, toolId: string): Promise<void> {
148→      const result = await api.delete(`/api/collections/${collectionId}/tools/${toolId}`);
149→      if (!result.ok) {
150→        throw new Error(
151→          `Failed to remove tool from collection: ${(result as { error: string }).error}`
152→        );
153→      }
154→    },
155→  };
156→}
157→
158→export type CollectionFactory = ReturnType<typeof createCollectionFactory>;
159→

  1→/**
  2→ * Authentication helpers for integration tests
  3→ *
  4→ * Provides utilities for creating authenticated fetch functions
  5→ * using session tokens, API keys, or cron secrets.
  6→ */
  7→
  8→export interface TestAuthContext {
  9→  userId: string;
 10→  username: string;
 11→  sessionToken: string;
 12→  apiKey: string;
 13→}
 14→
 15→/**
 16→ * Get test authentication context from environment variables
 17→ */
 18→export function getTestAuthContext(): TestAuthContext {
 19→  const sessionToken = process.env.INTEGRATION_TEST_SESSION_TOKEN;
 20→  const apiKey = process.env.INTEGRATION_TEST_API_KEY;
 21→  const userId = process.env.INTEGRATION_TEST_USER_ID || 'test-user-id';
 22→  const username = process.env.INTEGRATION_TEST_USERNAME || 'tpmjs-integration-test';
 23→
 24→  if (!sessionToken) {
 25→    throw new Error(
 26→      'INTEGRATION_TEST_SESSION_TOKEN not set. Run `pnpm --filter=@tpmjs/web test:setup-credentials` to generate.'
 27→    );
 28→  }
 29→
 30→  if (!apiKey) {
 31→    throw new Error(
 32→      'INTEGRATION_TEST_API_KEY not set. Run `pnpm --filter=@tpmjs/web test:setup-credentials` to generate.'
 33→    );
 34→  }
 35→
 36→  return {
 37→    userId,
 38→    username,
 39→    sessionToken,
 40→    apiKey,
 41→  };
 42→}
 43→
 44→/**
 45→ * Create a fetch function with session cookie authentication
 46→ *
 47→ * Note: better-auth uses different cookie names for HTTP vs HTTPS:
 48→ * - HTTP: better-auth.session_token
 49→ * - HTTPS: __Secure-better-auth.session_token
 50→ *
 51→ * We send both to ensure compatibility.
 52→ */
 53→export function createSessionFetch(sessionToken: string): typeof fetch {
 54→  return (input: RequestInfo | URL, init?: RequestInit) => {
 55→    const headers = new Headers(init?.headers);
 56→    // Send both cookie formats to work with both HTTP and HTTPS
 57→    headers.set(
 58→      'Cookie',
 59→      `better-auth.session_token=${sessionToken}; __Secure-better-auth.session_token=${sessionToken}`
 60→    );
 61→
 62→    return fetch(input, {
 63→      ...init,
 64→      headers,
 65→    });
 66→  };
 67→}
 68→
 69→/**
 70→ * Create a fetch function with API key authentication
 71→ */
 72→export function createApiKeyFetch(apiKey: string): typeof fetch {
 73→  return (input: RequestInfo | URL, init?: RequestInit) => {
 74→    const headers = new Headers(init?.headers);
 75→    headers.set('Authorization', `Bearer ${apiKey}`);
 76→
 77→    return fetch(input, {
 78→      ...init,
 79→      headers,
 80→    });
 81→  };
 82→}
 83→
 84→/**
 85→ * Create a fetch function with cron secret authentication
 86→ */
 87→export function createCronFetch(cronSecret?: string): typeof fetch {
 88→  const secret = cronSecret || process.env.CRON_SECRET;
 89→
 90→  if (!secret) {
 91→    throw new Error('CRON_SECRET not set');
 92→  }
 93→
 94→  return (input: RequestInfo | URL, init?: RequestInit) => {
 95→    const headers = new Headers(init?.headers);
 96→    headers.set('Authorization', `Bearer ${secret}`);
 97→
 98→    return fetch(input, {
 99→      ...init,
100→      headers,
101→    });
102→  };
103→}
104→
105→/**
106→ * Create all authenticated fetch functions
107→ */
108→export function createAuthenticatedFetches(auth: TestAuthContext): {
109→  sessionFetch: typeof fetch;
110→  apiKeyFetch: typeof fetch;
111→  cronFetch: typeof fetch;
112→} {
113→  return {
114→    sessionFetch: createSessionFetch(auth.sessionToken),
115→    apiKeyFetch: createApiKeyFetch(auth.apiKey),
116→    cronFetch: createCronFetch(),
117→  };
118→}
