  1→/**
  2→ * Authentication helpers for integration tests
  3→ *
  4→ * Provides utilities for creating authenticated fetch functions
  5→ * using session tokens, API keys, or cron secrets.
  6→ */
  7→
  8→export interface TestAuthContext {
  9→  userId: string;
 10→  username: string;
 11→  sessionToken: string;
 12→  apiKey: string;
 13→}
 14→
 15→/**
 16→ * Get test authentication context from environment variables
 17→ */
 18→export function getTestAuthContext(): TestAuthContext {
 19→  const sessionToken = process.env.INTEGRATION_TEST_SESSION_TOKEN;
 20→  const apiKey = process.env.INTEGRATION_TEST_API_KEY;
 21→  const userId = process.env.INTEGRATION_TEST_USER_ID || 'test-user-id';
 22→  const username = process.env.INTEGRATION_TEST_USERNAME || 'tpmjs-integration-test';
 23→
 24→  if (!sessionToken) {
 25→    throw new Error(
 26→      'INTEGRATION_TEST_SESSION_TOKEN not set. Run `pnpm --filter=@tpmjs/web test:setup-credentials` to generate.'
 27→    );
 28→  }
 29→
 30→  if (!apiKey) {
 31→    throw new Error(
 32→      'INTEGRATION_TEST_API_KEY not set. Run `pnpm --filter=@tpmjs/web test:setup-credentials` to generate.'
 33→    );
 34→  }
 35→
 36→  return {
 37→    userId,
 38→    username,
 39→    sessionToken,
 40→    apiKey,
 41→  };
 42→}
 43→
 44→/**
 45→ * Create a fetch function with session cookie authentication
 46→ *
 47→ * Note: better-auth uses different cookie names for HTTP vs HTTPS:
 48→ * - HTTP: better-auth.session_token
 49→ * - HTTPS: __Secure-better-auth.session_token
 50→ *
 51→ * We send both to ensure compatibility.
 52→ */
 53→export function createSessionFetch(sessionToken: string): typeof fetch {
 54→  return (input: RequestInfo | URL, init?: RequestInit) => {
 55→    const headers = new Headers(init?.headers);
 56→    // Send both cookie formats to work with both HTTP and HTTPS
 57→    headers.set(
 58→      'Cookie',
 59→      `better-auth.session_token=${sessionToken}; __Secure-better-auth.session_token=${sessionToken}`
 60→    );
 61→
 62→    return fetch(input, {
 63→      ...init,
 64→      headers,
 65→    });
 66→  };
 67→}
 68→
 69→/**
 70→ * Create a fetch function with API key authentication
 71→ */
 72→export function createApiKeyFetch(apiKey: string): typeof fetch {
 73→  return (input: RequestInfo | URL, init?: RequestInit) => {
 74→    const headers = new Headers(init?.headers);
 75→    headers.set('Authorization', `Bearer ${apiKey}`);
 76→
 77→    return fetch(input, {
 78→      ...init,
 79→      headers,
 80→    });
 81→  };
 82→}
 83→
 84→/**
 85→ * Create a fetch function with cron secret authentication
 86→ */
 87→export function createCronFetch(cronSecret?: string): typeof fetch {
 88→  const secret = cronSecret || process.env.CRON_SECRET;
 89→
 90→  if (!secret) {
 91→    throw new Error('CRON_SECRET not set');
 92→  }
 93→
 94→  return (input: RequestInfo | URL, init?: RequestInit) => {
 95→    const headers = new Headers(init?.headers);
 96→    headers.set('Authorization', `Bearer ${secret}`);
 97→
 98→    return fetch(input, {
 99→      ...init,
100→      headers,
101→    });
102→  };
103→}
104→
105→/**
106→ * Create all authenticated fetch functions
107→ */
108→export function createAuthenticatedFetches(auth: TestAuthContext): {
109→  sessionFetch: typeof fetch;
110→  apiKeyFetch: typeof fetch;
111→  cronFetch: typeof fetch;
112→} {
113→  return {
114→    sessionFetch: createSessionFetch(auth.sessionToken),
115→    apiKeyFetch: createApiKeyFetch(auth.apiKey),
116→    cronFetch: createCronFetch(),
117→  };
118→}
