140→    },
141→  });
142→
143→  // Delete test agent associations
144→  await prisma.agentTool.deleteMany({
145→    where: {
146→      agent: {
147→        userId,
148→        uid: { startsWith: 'test-' },
149→      },
150→    },
151→  });
152→  await prisma.agentCollection.deleteMany({
153→    where: {
154→      agent: {
155→        userId,
156→        uid: { startsWith: 'test-' },
157→      },
158→    },
159→  });
160→
161→  // Delete test agents
162→  const agentsResult = await prisma.agent.deleteMany({
163→    where: {
164→      userId,
165→      uid: { startsWith: 'test-' },
166→    },
167→  });
168→
169→  // Delete test collection associations
170→  await prisma.collectionTool.deleteMany({
171→    where: {
172→      collection: {
173→        userId,
174→        slug: { startsWith: 'test-' },
175→      },
176→    },
177→  });
178→
179→  // Delete test collections
180→  const collectionsResult = await prisma.collection.deleteMany({
181→    where: {
182→      userId,
183→      slug: { startsWith: 'test-' },
184→    },
185→  });
186→
187→  return {
188→    agents: agentsResult.count,
189→    collections: collectionsResult.count,
190→    conversations: conversationsResult.count,
191→  };
192→}
193→
194→/**
195→ * Clean up all test data for a specific user
196→ */
197→export async function cleanupAllTestData(userId: string): Promise<void> {
198→  // Delete all conversations for test agents
