  1→/**
  2→ * Agent Conversation Endpoint (Username/Slug-based version)
  3→ *
  4→ * POST: Send a message and stream the AI response
  5→ * GET: Retrieve conversation history
  6→ * DELETE: Delete a conversation
  7→ *
  8→ * This endpoint uses username and agent slug for public-friendly URLs.
  9→ * Example: /api/ajax/agents/tpmjs-discord/conversation/my-conv-1
 10→ *
 11→ * Authentication: Supports both session auth and TPMJS API key auth.
 12→ * Requires 'agent:chat' scope for API key access.
 13→ */
 14→
 15→import { Prisma, prisma } from '@tpmjs/db';
 16→import type { AIProvider } from '@tpmjs/types/agent';
 17→import { SendMessageSchema } from '@tpmjs/types/agent';
 18→import type { LanguageModel, ModelMessage } from 'ai';
 19→import { type NextRequest, NextResponse } from 'next/server';
 20→import { decryptApiKey } from '@/lib/crypto/api-keys';
 21→import { logActivity } from '~/lib/activity';
 22→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 23→import { trackUsage } from '~/lib/api-keys/usage';
 24→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 25→import { trackExecution } from '~/lib/tracking/executions';
 26→
 27→/**
 28→ * Rate limit for chat messages: 30 requests per minute
 29→ * This is stricter than default because chat involves expensive LLM calls
 30→ */
 31→const CHAT_RATE_LIMIT: RateLimitConfig = {
 32→  limit: 30,
 33→  windowSeconds: 60,
 34→};
 35→
 36→export const runtime = 'nodejs';
 37→export const dynamic = 'force-dynamic';
 38→export const maxDuration = 300; // 5 minutes for long agentic runs
 39→
 40→type RouteContext = {
 41→  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
 42→};
 43→
 44→/**
 45→ * Get AI provider SDK based on provider type
 46→ */
 47→async function getProviderModel(
 48→  provider: AIProvider,
 49→  modelId: string,
 50→  apiKey: string
 51→): Promise<LanguageModel> {
 52→  switch (provider) {
 53→    case 'OPENAI': {
 54→      const { createOpenAI } = await import('@ai-sdk/openai');
 55→      return createOpenAI({ apiKey })(modelId);
 56→    }
 57→    case 'ANTHROPIC': {
 58→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 59→      return createAnthropic({ apiKey })(modelId);
 60→    }
 61→    case 'GOOGLE': {
 62→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 63→      return createGoogleGenerativeAI({ apiKey })(modelId);
 64→    }
 65→    case 'GROQ': {
 66→      const { createGroq } = await import('@ai-sdk/groq');
 67→      return createGroq({ apiKey })(modelId);
 68→    }
 69→    case 'MISTRAL': {
 70→      const { createMistral } = await import('@ai-sdk/mistral');
 71→      return createMistral({ apiKey })(modelId);
 72→    }
 73→    default:
 74→      throw new Error(`Unsupported provider: ${provider}`);
 75→  }
 76→}
 77→
 78→/**
 79→ * POST /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 80→ * Send a message and stream the AI response via SSE
 81→ */
 82→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 83→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 84→  const startTime = Date.now();
 85→
 86→  // Authenticate request (supports both session and API key)
 87→  const authResult = await authenticateRequest();
 88→
 89→  if (!authResult.authenticated) {
 90→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 91→  }
 92→
 93→  // Check scope for API key auth
 94→  if (authResult.authenticated && !authResult.isSessionAuth) {
 95→    if (!hasScope(authResult, 'agent:chat')) {
 96→      return NextResponse.json(
 97→        { error: 'API key does not have agent:chat scope' },
 98→        { status: 403 }
 99→      );
100→    }
101→  }
102→
103→  // Check rate limit (after auth so we can track by user if needed)
104→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
105→  if (rateLimitResponse) {
106→    return rateLimitResponse;
107→  }
108→
109→  const { username, agentSlug, conversationId } = await context.params;
110→
111→  try {
112→    const body = await request.json();
113→    const parsed = SendMessageSchema.safeParse(body);
114→    if (!parsed.success) {
115→      return NextResponse.json(
116→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
117→        { status: 400 }
118→      );
119→    }
120→
121→    // Fetch agent by username and slug with all tool relations
122→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
123→      '@/lib/agents/build-tools'
124→    );
125→    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Owner-only enforcement: Only the agent owner can chat with the agent
132→    if (authResult.userId !== agent.userId) {
133→      return NextResponse.json(
134→        {
135→          success: false,
136→          error:
137→            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
138→            'Visit the agent page to fork it to your account.',
139→        },
140→        { status: 403 }
141→      );
142→    }
143→
144→    // Map provider to expected key name format
145→    const providerKeyNames: Record<string, string> = {
146→      OPENAI: 'OPENAI_API_KEY',
147→      ANTHROPIC: 'ANTHROPIC_API_KEY',
148→      GOOGLE: 'GOOGLE_API_KEY',
149→      GROQ: 'GROQ_API_KEY',
150→      MISTRAL: 'MISTRAL_API_KEY',
151→    };
152→    const keyName = providerKeyNames[agent.provider];
153→
154→    if (!keyName) {
155→      return NextResponse.json(
156→        { success: false, error: `Unsupported provider: ${agent.provider}` },
157→        { status: 400 }
158→      );
159→    }
160→
161→    // Get user's API key for this provider
162→    const userApiKey = await prisma.userApiKey.findUnique({
163→      where: {
164→        userId_keyName: {
165→          userId: agent.userId,
166→          keyName,
167→        },
168→      },
169→    });
170→
171→    if (!userApiKey) {
172→      return NextResponse.json(
173→        {
174→          success: false,
175→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→        },
177→        { status: 400 }
178→      );
179→    }
180→
181→    // Decrypt the API key
182→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→
184→    // Get or create conversation
185→    let conversation = await prisma.conversation.findUnique({
186→      where: {
187→        agentId_slug: {
188→          agentId: agent.id,
189→          slug: conversationId,
190→        },
191→      },
192→    });
193→
194→    if (!conversation) {
195→      conversation = await prisma.conversation.create({
196→        data: {
197→          agentId: agent.id,
198→          slug: conversationId,
199→          title: parsed.data.message.slice(0, 100),
200→        },
201→      });
202→
203→      // Log activity for new conversation (fire-and-forget)
204→      if (agent.userId) {
205→        logActivity({
206→          userId: agent.userId,
207→          type: 'AGENT_CONVERSATION_STARTED',
208→          targetName: agent.name,
209→          targetType: 'agent',
210→          agentId: agent.id,
211→        });
212→      }
213→    }
214→
215→    // Fetch recent messages for context
216→    const recentMessages = await prisma.message.findMany({
217→      where: { conversationId: conversation.id },
218→      orderBy: { createdAt: 'desc' },
219→      take: agent.maxMessagesInContext,
220→    });
221→
222→    // Reverse to get chronological order
223→    recentMessages.reverse();
224→
225→    // Save user message
226→    await prisma.message.create({
227→      data: {
228→        conversationId: conversation.id,
229→        role: 'USER',
230→        content: parsed.data.message,
231→      },
232→    });
233→
234→    // Build AI SDK messages from conversation history
235→    const { streamText, stepCountIs } = await import('ai');
236→
237→    const messages: ModelMessage[] = [];
238→
239→    // Add system prompt if defined
240→    if (agent.systemPrompt) {
241→      messages.push({
242→        role: 'system',
243→        content: agent.systemPrompt,
244→      });
245→    }
246→
247→    // Build a set of tool call IDs that have corresponding tool results
248→    // This is needed because AI SDK requires every tool call to have a matching tool result
249→    const toolResultIds = new Set(
250→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
251→    );
252→
253→    // Add conversation history - properly format for AI SDK
254→    for (const msg of recentMessages) {
255→      if (msg.role === 'USER') {
256→        messages.push({ role: 'user', content: msg.content });
257→      } else if (msg.role === 'ASSISTANT') {
258→        // For assistant messages with tool calls, include ToolCallParts in content
259→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
260→          // Only include tool calls that have matching tool results
261→          // AI SDK fails if there's a tool call without a corresponding tool result
262→          const validToolCalls = (
263→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
264→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
265→
266→          if (validToolCalls.length > 0) {
267→            const toolCallParts = validToolCalls.map((tc) => ({
268→              type: 'tool-call' as const,
269→              toolCallId: tc.toolCallId,
270→              toolName: tc.toolName,
271→              input: tc.args,
272→            }));
273→            // Content includes text (if any) plus tool call parts
274→            const content: Array<
275→              | { type: 'text'; text: string }
276→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
277→            > = [];
278→            if (msg.content) {
279→              content.push({ type: 'text', text: msg.content });
280→            }
281→            content.push(...toolCallParts);
282→            messages.push({
283→              role: 'assistant',
284→              content,
285→            });
286→          } else {
287→            // All tool calls are missing results, just include text content
288→            messages.push({
289→              role: 'assistant',
290→              content: msg.content || '',
291→            });
292→          }
293→        } else {
294→          messages.push({
295→            role: 'assistant',
296→            content: msg.content,
297→          });
298→        }
299→      } else if (msg.role === 'TOOL') {
300→        // Tool results use the 'tool' role with content array
301→        messages.push({
302→          role: 'tool',
303→          content: [
304→            {
305→              type: 'tool-result' as const,
306→              toolCallId: msg.toolCallId || '',
307→              toolName: msg.toolName || '',
308→              output: {
309→                type: 'json' as const,
310→                value: msg.toolResult,
311→              },
312→            },
313→          ],
314→        });
315→      }
316→    }
317→
318→    // Add new user message
319→    messages.push({ role: 'user', content: parsed.data.message });
320→
321→    // Set up sandbox session if agent uses sandbox executor
322→    let sessionId: string | undefined;
323→    if (agent.executorType === 'sandbox') {
324→      const { parseExecutorConfig, resolveSandboxUrl, createSandboxSession } = await import(
325→        '@/lib/executors'
326→      );
327→      const sandboxConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
328→      if (sandboxConfig && sandboxConfig.type === 'sandbox') {
329→        const sandboxUrl = resolveSandboxUrl(sandboxConfig);
330→        if (!sandboxUrl) {
331→          return NextResponse.json(
332→            {
333→              success: false,
334→              error:
335→                'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom sandbox URL.',
336→            },
337→            { status: 502 }
338→          );
339→        }
340→        sessionId = `${agent.id}:${conversationId}`;
341→        try {
342→          await createSandboxSession(sandboxUrl, sandboxConfig.apiKey, sessionId);
343→        } catch (error) {
344→          console.error('[Sandbox] Failed to create session:', error);
345→          return NextResponse.json(
346→            {
347→              success: false,
348→              error: `Failed to create sandbox session: ${error instanceof Error ? error.message : 'Unknown error'}`,
349→            },
350→            { status: 502 }
351→          );
352→        }
353→      }
354→    }
355→
356→    // Build tools from agent configuration
357→    const tools = buildAgentTools(agent, undefined, sessionId);
358→
359→    // Get the provider model
360→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
361→
362→    // Create SSE stream
363→    const stream = new ReadableStream({
364→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
365→      async start(controller) {
366→        const encoder = new TextEncoder();
367→
368→        const sendEvent = (event: string, data: unknown) => {
369→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
370→          controller.enqueue(encoder.encode(message));
371→        };
372→
373→        try {
374→          const startTime = Date.now();
375→          let fullContent = '';
376→          // Accumulate tool calls with their input args
377→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
378→            new Map();
379→          // Collect tool results to save AFTER assistant message (for correct chronological order)
380→          const pendingToolResults: Array<{
381→            toolCallId: string;
382→            toolName: string;
383→            output: unknown;
384→          }> = [];
385→          let inputTokens = 0;
386→          let outputTokens = 0;
387→
388→          // Stream the response with agentic loop control
389→          const result = await streamText({
390→            model,
391→            messages,
392→            tools,
393→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
394→            onChunk: async ({ chunk }) => {
395→              // Stream tool calls as they come in and capture their inputs
396→              if (chunk.type === 'tool-call') {
397→                const input = 'args' in chunk ? chunk.args : chunk.input;
398→
399→                // Log tool call for debugging
400→                console.log('[Agent] Tool call initiated:', {
401→                  toolName: chunk.toolName,
402→                  toolCallId: chunk.toolCallId,
403→                  input: JSON.stringify(input).slice(0, 500),
404→                });
405→
406→                // Store tool call with input for later persistence
407→                toolCallsMap.set(chunk.toolCallId, {
408→                  toolCallId: chunk.toolCallId,
409→                  toolName: chunk.toolName,
410→                  args: input,
411→                });
412→                sendEvent('tool_call', {
413→                  toolCallId: chunk.toolCallId,
414→                  toolName: chunk.toolName,
415→                  input,
416→                });
417→              }
418→            },
419→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
420→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
421→              // Capture tool calls from step finish (backup in case onChunk missed any)
422→              if (toolCalls && Array.isArray(toolCalls)) {
423→                for (const tc of toolCalls) {
424→                  if (!toolCallsMap.has(tc.toolCallId)) {
425→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
426→                    const args =
427→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
428→                    toolCallsMap.set(tc.toolCallId, {
429→                      toolCallId: tc.toolCallId,
430→                      toolName: tc.toolName,
431→                      args,
432→                    });
433→                  }
434→                }
435→              }
436→
437→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
438→              if (toolResults && toolResults.length > 0) {
439→                for (const tr of toolResults) {
440→                  // Check if this is an error result (AI SDK wraps errors in the output)
441→                  const isError =
442→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
443→
444→                  // Log tool results for debugging
445→                  if (isError) {
446→                    console.error('[Agent] Tool execution failed:', {
447→                      toolName: tr.toolName,
448→                      toolCallId: tr.toolCallId,
449→                      error: tr.output,
450→                    });
451→                  } else {
452→                    console.log('[Agent] Tool execution success:', {
453→                      toolName: tr.toolName,
454→                      toolCallId: tr.toolCallId,
455→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
456→                    });
457→                  }
458→
459→                  sendEvent('tool_result', {
460→                    toolCallId: tr.toolCallId,
461→                    output: tr.output,
462→                    isError,
463→                  });
464→
465→                  // Collect tool results to save after assistant message
466→                  pendingToolResults.push({
467→                    toolCallId: tr.toolCallId,
468→                    toolName: tr.toolName,
469→                    output: tr.output,
470→                  });
471→
472→                  // Track each tool call execution event
473→                  trackExecution({
474→                    eventType: 'tool_call',
475→                    source: 'agent_chat',
476→                    userId: authResult.userId ?? undefined,
477→                    apiKeyId: authResult.apiKeyId ?? undefined,
478→                    agentId: agent.id,
479→                    toolName: tr.toolName,
480→                    status: isError ? 'error' : 'success',
481→                  });
482→                }
483→              }
484→
485→              // Track token usage
486→              if (usage) {
487→                inputTokens += usage.inputTokens ?? 0;
488→                outputTokens += usage.outputTokens ?? 0;
489→              }
490→            },
491→          });
492→
493→          // Stream text chunks
494→          for await (const chunk of result.textStream) {
495→            fullContent += chunk;
496→            sendEvent('chunk', { type: 'text', text: chunk });
497→          }
498→
499→          // Get final response data
500→          const finalUsage = await result.usage;
501→
502→          // Convert tool calls map to array for storage
503→          const allToolCalls = Array.from(toolCallsMap.values());
504→
505→          // Update token counts from final usage
506→          if (finalUsage) {
507→            inputTokens = finalUsage.inputTokens ?? inputTokens;
508→            outputTokens = finalUsage.outputTokens ?? outputTokens;
509→          }
510→
511→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
512→          const assistantMessage = await prisma.message.create({
513→            data: {
514→              conversationId: conversation.id,
515→              role: 'ASSISTANT',
516→              content: fullContent,
517→              // Cast to Prisma-compatible JSON type
518→              toolCalls:
519→                allToolCalls.length > 0
520→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
521→                  : Prisma.JsonNull,
522→              inputTokens,
523→              outputTokens,
524→            },
525→          });
526→
527→          // Now save TOOL messages (after assistant, for correct chronological order)
528→          for (const tr of pendingToolResults) {
529→            await prisma.message.create({
530→              data: {
531→                conversationId: conversation.id,
532→                role: 'TOOL',
533→                content: JSON.stringify(tr.output),
534→                toolCallId: tr.toolCallId,
535→                toolName: tr.toolName,
536→                toolResult: tr.output as object,
537→              },
538→            });
539→          }
540→
541→          // Update conversation timestamp
542→          await prisma.conversation.update({
543→            where: { id: conversation.id },
544→            data: { updatedAt: new Date() },
545→          });
546→
547→          const executionTimeMs = Date.now() - startTime;
548→
549→          // Send token usage
550→          sendEvent('tokens', {
551→            inputTokens,
552→            outputTokens,
553→            totalTokens: inputTokens + outputTokens,
554→          });
555→
556→          // Send completion event
557→          sendEvent('complete', {
558→            messageId: assistantMessage.id,
559→            conversationId: conversation.id,
560→            executionTimeMs,
561→          });
562→
563→          // Track agent run execution event
564→          trackExecution({
565→            eventType: 'agent_run',
566→            source: 'agent_chat',
567→            userId: authResult.userId ?? undefined,
568→            apiKeyId: authResult.apiKeyId ?? undefined,
569→            agentId: agent.id,
570→            status: 'success',
571→            durationMs: executionTimeMs,
572→            tokensIn: inputTokens,
573→            tokensOut: outputTokens,
574→          });
575→
576→          // Track usage
577→          if (authResult.userId) {
578→            trackUsage({
579→              apiKeyId: authResult.apiKeyId ?? undefined,
580→              userId: authResult.userId,
581→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
582→              method: 'POST',
583→              statusCode: 200,
584→              latencyMs: executionTimeMs,
585→              resourceType: 'agent',
586→              resourceId: agent.id,
587→              tokensIn: inputTokens,
588→              tokensOut: outputTokens,
589→              model: agent.modelId,
590→            });
591→          }
592→        } catch (error) {
593→          // Log detailed error for debugging
594→          console.error('[Agent] Conversation stream error:', {
595→            error: error instanceof Error ? error.message : String(error),
596→            stack: error instanceof Error ? error.stack : undefined,
597→            agentId: agent.id,
598→            conversationId: conversation.id,
599→          });
600→          sendEvent('error', {
601→            message: error instanceof Error ? error.message : 'Unknown error',
602→          });
603→
604→          // Track agent run error
605→          trackExecution({
606→            eventType: 'agent_run',
607→            source: 'agent_chat',
608→            userId: authResult.userId ?? undefined,
609→            apiKeyId: authResult.apiKeyId ?? undefined,
610→            agentId: agent.id,
611→            status: 'error',
612→            durationMs: Date.now() - startTime,
613→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
614→          });
615→
616→          // Track error
617→          if (authResult.userId) {
618→            trackUsage({
619→              apiKeyId: authResult.apiKeyId ?? undefined,
620→              userId: authResult.userId,
621→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
622→              method: 'POST',
623→              statusCode: 500,
624→              latencyMs: Date.now() - startTime,
625→              resourceType: 'agent',
626→              resourceId: agent.id,
627→              errorCode: 'STREAM_ERROR',
628→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
629→            });
630→          }
631→        } finally {
632→          controller.close();
633→        }
634→      },
635→    });
636→
637→    return new NextResponse(stream, {
638→      headers: {
639→        'Content-Type': 'text/event-stream',
640→        'Cache-Control': 'no-cache',
641→        Connection: 'keep-alive',
642→      },
643→    });
644→  } catch (error) {
645→    console.error('Failed to process message:', error);
646→    return NextResponse.json(
647→      {
648→        success: false,
649→        error: error instanceof Error ? error.message : 'Failed to process message',
650→      },
651→      { status: 500 }
652→    );
653→  }
654→}
