656→/**
657→ * GET /api/[username]/agents/[agentSlug]/conversation/[conversationId]
658→ * Retrieve conversation history with pagination
659→ */
660→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
661→  const { username, agentSlug, conversationId } = await context.params;
662→  const { searchParams } = new URL(request.url);
663→
664→  const format = searchParams.get('format');
665→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
666→  const before = searchParams.get('before');
667→  const after = searchParams.get('after');
668→
669→  try {
670→    // Fetch agent by username and slug
671→    const agent = await prisma.agent.findFirst({
672→      where: {
673→        uid: agentSlug,
674→        user: { username },
675→      },
676→      select: {
677→        id: true,
678→        uid: true,
679→        name: true,
680→        provider: true,
681→        modelId: true,
682→        executorType: true,
683→        executorConfig: true,
684→      },
685→    });
686→
687→    if (!agent) {
688→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
689→    }
690→
691→    // Fetch conversation
692→    const conversation = await prisma.conversation.findUnique({
693→      where: {
694→        agentId_slug: {
695→          agentId: agent.id,
696→          slug: conversationId,
697→        },
698→      },
699→    });
700→
701→    if (!conversation) {
702→      return NextResponse.json(
703→        { success: false, error: 'Conversation not found' },
704→        { status: 404 }
705→      );
706→    }
707→
708→    // For JSON format, return all messages with full details
709→    if (format === 'json') {
710→      const allMessages = await prisma.message.findMany({
711→        where: { conversationId: conversation.id },
712→        orderBy: { createdAt: 'asc' },
713→      });
714→
715→      const response = {
716→        _meta: {
717→          exportedAt: new Date().toISOString(),
718→          format: 'tpmjs-conversation-log',
719→          version: '1.0',
720→        },
721→        agent: {
722→          id: agent.id,
723→          uid: agent.uid,
724→          name: agent.name,
725→          provider: agent.provider,
726→          modelId: agent.modelId,
727→          executorType: agent.executorType,
728→          executorConfig: agent.executorConfig,
729→        },
730→        conversation: {
731→          id: conversation.id,
732→          slug: conversation.slug,
733→          title: conversation.title,
734→          createdAt: conversation.createdAt,
735→          updatedAt: conversation.updatedAt,
736→          messageCount: allMessages.length,
737→        },
738→        messages: allMessages.map((m) => ({
739→          id: m.id,
740→          role: m.role,
741→          content: m.content,
742→          toolCalls: m.toolCalls,
743→          toolCallId: m.toolCallId,
744→          toolName: m.toolName,
745→          toolResult: m.toolResult,
746→          inputTokens: m.inputTokens,
747→          outputTokens: m.outputTokens,
748→          createdAt: m.createdAt,
749→        })),
750→        stats: {
751→          totalMessages: allMessages.length,
752→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
753→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
754→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
755→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
756→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
757→        },
758→      };
759→
760→      // Return pretty-printed JSON with proper content type
761→      return new NextResponse(JSON.stringify(response, null, 2), {
762→        headers: {
763→          'Content-Type': 'application/json',
764→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
765→        },
766→      });
767→    }
768→
769→    // Standard paginated response
770→    const whereClause: {
771→      conversationId: string;
772→      createdAt?: { lt?: Date; gt?: Date };
773→    } = { conversationId: conversation.id };
774→
775→    if (before) {
776→      whereClause.createdAt = { lt: new Date(before) };
777→    } else if (after) {
778→      whereClause.createdAt = { gt: new Date(after) };
779→    }
780→
781→    // Determine fetch order:
782→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
783→    // - "after": Fetch asc (oldest first) to get messages after the cursor
784→    const shouldFetchDesc = !after;
785→
786→    // Fetch messages
787→    const messages = await prisma.message.findMany({
788→      where: whereClause,
789→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
790→      take: limit + 1,
791→    });
792→
793→    const hasMore = messages.length > limit;
794→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
795→
796→    // Reverse if we fetched in desc order to maintain chronological order
797→    if (shouldFetchDesc) {
798→      paginatedMessages = paginatedMessages.reverse();
799→    }
800→
801→    const mappedMessages = paginatedMessages.map((m) => ({
802→      id: m.id,
803→      role: m.role,
804→      content: m.content,
805→      toolCalls: m.toolCalls,
806→      toolCallId: m.toolCallId,
807→      toolName: m.toolName,
808→      toolResult: m.toolResult,
809→      inputTokens: m.inputTokens,
810→      outputTokens: m.outputTokens,
811→      createdAt: m.createdAt,
812→    }));
813→
814→    return NextResponse.json({
815→      success: true,
816→      data: {
817→        id: conversation.id,
818→        slug: conversation.slug,
819→        title: conversation.title,
820→        createdAt: conversation.createdAt,
821→        updatedAt: conversation.updatedAt,
822→        messages: mappedMessages,
823→      },
824→      pagination: {
825→        limit,
826→        hasMore,
827→        ...(before && { before }),
828→        ...(after && { after }),
829→      },
830→    });
831→  } catch (error) {
832→    console.error('Failed to fetch conversation:', error);
833→    return NextResponse.json(
834→      { success: false, error: 'Failed to fetch conversation' },
835→      { status: 500 }
836→    );
837→  }
838→}
