840→/**
841→ * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
842→ * Delete a conversation
843→ */
844→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
845→  const { username, agentSlug, conversationId } = await context.params;
846→
847→  try {
848→    // Fetch agent by username and slug (include executor fields for sandbox cleanup)
849→    const agent = await prisma.agent.findFirst({
850→      where: {
851→        uid: agentSlug,
852→        user: { username },
853→      },
854→      select: { id: true, executorType: true, executorConfig: true },
855→    });
856→
857→    if (!agent) {
858→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
859→    }
860→
861→    // Destroy sandbox session if applicable (fire-and-forget)
862→    if (agent.executorType === 'sandbox') {
863→      const { parseExecutorConfig, resolveSandboxUrl, destroySandboxSession } = await import(
864→        '@/lib/executors'
865→      );
866→      const sandboxConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
867→      if (sandboxConfig && sandboxConfig.type === 'sandbox') {
868→        const sandboxUrl = resolveSandboxUrl(sandboxConfig);
869→        if (sandboxUrl) {
870→          const sessionId = `${agent.id}:${conversationId}`;
871→          destroySandboxSession(sandboxUrl, sandboxConfig.apiKey, sessionId).catch(() => {});
872→        }
873→      }
874→    }
875→
876→    // Delete conversation (messages cascade)
877→    await prisma.conversation.deleteMany({
878→      where: {
879→        agentId: agent.id,
880→        slug: conversationId,
881→      },
882→    });
883→
884→    return NextResponse.json({
885→      success: true,
886→      data: { deleted: true },
887→    });
888→  } catch (error) {
889→    console.error('Failed to delete conversation:', error);
890→    return NextResponse.json(
891→      { success: false, error: 'Failed to delete conversation' },
892→      { status: 500 }
893→    );
894→  }
895→}
