 89→/**
 90→ * Execute a tool using a custom URL executor
 91→ */
 92→async function executeWithCustomUrl(
 93→  url: string,
 94→  apiKey: string | undefined,
 95→  request: ExecuteToolRequest,
 96→  timeout: number = DEFAULT_TIMEOUT
 97→): Promise<ExecuteToolResponse> {
 98→  const startTime = Date.now();
 99→
100→  const headers: Record<string, string> = {
101→    'Content-Type': 'application/json',
102→  };
103→
104→  if (apiKey) {
105→    headers.Authorization = `Bearer ${apiKey}`;
106→  }
107→
108→  try {
109→    const controller = new AbortController();
110→    const timeoutId = setTimeout(() => controller.abort(), timeout);
111→
112→    const response = await fetch(`${url}/execute-tool`, {
113→      method: 'POST',
114→      headers,
115→      body: JSON.stringify(request),
116→      signal: controller.signal,
117→    });
118→
119→    clearTimeout(timeoutId);
120→
121→    const executionTimeMs = Date.now() - startTime;
122→
123→    if (!response.ok) {
124→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
125→        error?: string;
126→      };
127→      return {
128→        success: false,
129→        error: errorData.error || `Executor error: ${response.status}`,
130→        executionTimeMs,
131→      };
132→    }
133→
134→    const result = (await response.json()) as ExecuteToolResponse;
135→
136→    return {
137→      success: result.success,
138→      output: result.output,
139→      error: result.error,
140→      executionTimeMs: result.executionTimeMs || executionTimeMs,
141→    };
142→  } catch (error) {
143→    const executionTimeMs = Date.now() - startTime;
144→
145→    if (error instanceof Error && error.name === 'AbortError') {
146→      return {
147→        success: false,
148→        error: 'Execution timeout',
149→        executionTimeMs,
150→      };
151→    }
152→
153→    return {
154→      success: false,
155→      error: error instanceof Error ? error.message : String(error),
156→      executionTimeMs,
157→    };
158→  }
159→}
