217→/**
218→ * Destroy a sandbox session (fire-and-forget safe)
219→ * Returns gracefully even if the session doesn't exist.
220→ */
221→export async function destroySandboxSession(
222→  url: string,
223→  apiKey: string | undefined,
224→  sessionId: string
225→): Promise<DestroySessionResponse> {
226→  const headers: Record<string, string> = {};
227→  if (apiKey) {
228→    headers.Authorization = `Bearer ${apiKey}`;
229→  }
230→
231→  try {
232→    const controller = new AbortController();
233→    const timeoutId = setTimeout(() => controller.abort(), 10000);
234→
235→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
236→      method: 'DELETE',
237→      headers,
238→      signal: controller.signal,
239→    });
240→
241→    clearTimeout(timeoutId);
242→
243→    if (!response.ok && response.status !== 404) {
244→      return { sessionId, destroyed: false };
245→    }
246→
247→    return (await response
248→      .json()
249→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
250→  } catch {
251→    // Fire-and-forget: don't throw on cleanup failures
252→    return { sessionId, destroyed: false };
253→  }
254→}
