195→/**
196→ * Parse environment variables from JSON field
197→ * Returns empty object if null/undefined or invalid
198→ */
199→function parseEnvVars(envVars: unknown): Record<string, string> {
200→  if (!envVars || typeof envVars !== 'object') {
201→    return {};
202→  }
203→  // Validate all values are strings
204→  const result: Record<string, string> = {};
205→  for (const [key, value] of Object.entries(envVars)) {
206→    if (typeof value === 'string') {
207→      result[key] = value;
208→    }
209→  }
210→  return result;
211→}
