222→/**
223→ * Execute tool with AI agent using AI SDK v6
224→ * Requires Tool with Package relation
225→ */
226→export async function executeToolWithAgent(
227→  tool: Tool & { package: Package },
228→  userPrompt: string,
229→  onChunk?: (chunk: string) => void,
230→  onTokenUpdate?: (tokens: Partial<TokenBreakdown>) => void
231→) {
232→  const toolDef = createToolDefinition(tool);
233→  const sanitizedToolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
234→
235→  console.log('[executeToolWithAgent] Tool name:', sanitizedToolName);
236→
237→  const messages: ModelMessage[] = [
238→    {
239→      role: 'user',
240→      content: userPrompt,
241→    },
242→  ];
243→
244→  const toolsConfig = {
245→    [sanitizedToolName]: toolDef,
246→  };
247→
248→  console.log('[executeToolWithAgent] Calling generateText');
249→
250→  // Use generateText for tool execution
251→  const result = await generateText({
252→    model: openai('gpt-4-turbo'),
253→    messages,
254→    tools: toolsConfig,
255→  });
256→
257→  console.log('[executeToolWithAgent] Result:', JSON.stringify(result, null, 2));
258→
259→  // Extract tool results from the response
260→  let toolOutput: unknown = null;
261→  if (result.response?.messages) {
262→    for (const message of result.response.messages) {
263→      if (message.role === 'tool' && 'content' in message) {
264→        toolOutput = message.content;
265→        console.log('[executeToolWithAgent] Tool output found:', toolOutput);
266→        break;
267→      }
268→    }
269→  }
270→
271→  // Format the output as JSON
272→  const fullOutput = toolOutput
273→    ? JSON.stringify(toolOutput, null, 2)
274→    : result.text || JSON.stringify(result, null, 2);
275→
276→  console.log('[executeToolWithAgent] Final output:', fullOutput);
277→
278→  // Stream the output (all at once since generateText is non-streaming)
279→  if (onChunk) {
280→    onChunk(fullOutput);
281→  }
282→
283→  // Calculate final token breakdown
284→  const parameters = Array.isArray(tool.parameters)
285→    ? (tool.parameters as unknown as TPMJSParameter[])
286→    : [];
287→  const tokenBreakdown = calculateTokenBreakdown(
288→    userPrompt,
289→    tool.description,
290→    parameters,
291→    tool.returns,
292→    fullOutput
293→  );
294→
295→  onTokenUpdate?.(tokenBreakdown);
296→
297→  return {
298→    output: fullOutput,
299→    tokenBreakdown,
300→    agentSteps: result.steps?.length || 1,
301→  };
302→}
