344→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool execution with session support
345→async function handleExecuteTool(req: Request): Promise<Response> {
346→  const startTime = Date.now();
347→
348→  try {
349→    const body = await req.json();
350→    const { packageName, name, version, importUrl, params, env, sessionId } = body;
351→
352→    if (!packageName || !name) {
353→      return Response.json(
354→        { success: false, error: 'Missing required fields: packageName, name' },
355→        { status: 400, headers: corsHeaders() }
356→      );
357→    }
358→
359→    // Load the tool
360→    const tool = await loadTool(packageName, name, version || 'latest', importUrl);
361→
362→    if (!tool || typeof tool.execute !== 'function') {
363→      return Response.json(
364→        { success: false, error: `"${name}" is not a valid tool (missing execute function)` },
365→        { status: 400, headers: corsHeaders() }
366→      );
367→    }
368→
369→    // Resolve session workspace for cwd if sessionId provided
370→    let cwd: string | undefined;
371→    if (sessionId) {
372→      const session = getSession(sessionId);
373→      if (session) {
374→        cwd = session.workDir;
375→        session.toolCallCount++;
376→        // Extend session TTL on each tool call
377→        session.expiresAt = new Date(Date.now() + DEFAULT_SESSION_TTL_SECONDS * 1000);
378→      }
379→    }
380→
381→    // Set environment variables if provided
382→    if (env && typeof env === 'object') {
383→      for (const [key, value] of Object.entries(env)) {
384→        if (typeof value === 'string') {
385→          Deno.env.set(key, value);
386→        }
387→      }
388→    }
389→
390→    // Execute the tool, injecting cwd into params if session is active
391→    const executeParams = cwd ? { ...params, _sandboxWorkDir: cwd } : params;
392→    const output = await tool.execute(executeParams);
393→
394→    // Clean up injected env vars
395→    if (env && typeof env === 'object') {
396→      for (const key of Object.keys(env)) {
397→        try {
398→          Deno.env.delete(key);
399→        } catch {
400→          // Some vars may be read-only
401→        }
402→      }
403→    }
404→
405→    const executionTimeMs = Date.now() - startTime;
406→
407→    return Response.json(
408→      { success: true, output, executionTimeMs },
409→      { status: 200, headers: corsHeaders() }
410→    );
411→  } catch (error) {
412→    const executionTimeMs = Date.now() - startTime;
413→    const message = error instanceof Error ? error.message : String(error);
414→    console.error('❌ Execute tool error:', message);
415→
416→    return Response.json(
417→      { success: false, error: message, executionTimeMs },
418→      { status: 200, headers: corsHeaders() }
419→    );
420→  }
421→}
