444→// ─── Request Router ─────────────────────────────────────────────────────────
445→
446→async function handler(req: Request): Promise<Response> {
447→  const url = new URL(req.url);
448→  const { pathname } = url;
449→  const method = req.method;
450→
451→  // CORS preflight
452→  if (method === 'OPTIONS') {
453→    return new Response(null, { status: 204, headers: corsHeaders() });
454→  }
455→
456→  // Health check (no auth required)
457→  if (pathname === '/health' && method === 'GET') {
458→    return handleHealth();
459→  }
460→
461→  // Auth check for all other routes
462→  if (!checkAuth(req)) {
463→    return Response.json({ error: 'Unauthorized' }, { status: 401, headers: corsHeaders() });
464→  }
465→
466→  // Session endpoints
467→  if (pathname === '/sessions' && method === 'POST') {
468→    return handleCreateSession(req);
469→  }
470→
471→  const sessionMatch = pathname.match(/^\/sessions\/(.+)$/);
472→  if (sessionMatch) {
473→    const sessionId = decodeURIComponent(sessionMatch[1]);
474→    if (method === 'GET') {
475→      return handleGetSession(sessionId);
476→    }
477→    if (method === 'DELETE') {
478→      return handleDestroySession(sessionId);
479→    }
480→  }
481→
482→  // Tool execution
483→  if (pathname === '/execute-tool' && method === 'POST') {
484→    return handleExecuteTool(req);
485→  }
486→
487→  return Response.json({ error: 'Not Found' }, { status: 404, headers: corsHeaders() });
488→}
489→
490→// ─── Server Startup ─────────────────────────────────────────────────────────
491→
492→// Ensure sessions directory exists
493→try {
494→  await Deno.mkdir(SESSIONS_BASE_DIR, { recursive: true });
495→} catch {
496→  // May already exist
497→}
498→
499→console.log(`🚀 TPMJS Agent Sandbox Server starting on port ${PORT}`);
500→console.log(`📁 Sessions base dir: ${SESSIONS_BASE_DIR}`);
501→console.log(`🔒 Auth: ${EXECUTOR_API_KEY ? 'enabled' : 'disabled'}`);
502→console.log(`📊 Max sessions: ${MAX_CONCURRENT_SESSIONS}, TTL: ${DEFAULT_SESSION_TTL_SECONDS}s`);
503→
504→Deno.serve({ port: PORT }, handler);
505→
506→// ─── Graceful Shutdown ──────────────────────────────────────────────────────
507→
508→async function shutdown(signal: string) {
509→  console.log(`\n${signal} received. Cleaning up ${sessions.size} sessions...`);
510→
511→  // Destroy all sessions
512→  for (const sessionId of sessions.keys()) {
513→    await destroySession(sessionId).catch(() => {});
514→  }
515→
516→  console.log('✅ Cleanup complete. Exiting.');
517→  Deno.exit(0);
518→}
519→
520→Deno.addSignalListener('SIGTERM', () => shutdown('SIGTERM'));
521→Deno.addSignalListener('SIGINT', () => shutdown('SIGINT'));
