  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→  SandboxExecutorConfig,
 17→} from '@tpmjs/types/executor';
 18→
 19→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 20→
 21→/**
 22→ * Resolve executor configuration using cascade:
 23→ * Agent Config → Collection Config → System Default
 24→ *
 25→ * @param agentConfig - Executor config from Agent (highest priority)
 26→ * @param collectionConfig - Executor config from Collection (medium priority)
 27→ * @returns Resolved executor configuration
 28→ */
 29→export function resolveExecutorConfig(
 30→  agentConfig: ExecutorConfig | null | undefined,
 31→  collectionConfig: ExecutorConfig | null | undefined
 32→): ExecutorConfig {
 33→  // Agent config takes precedence
 34→  if (agentConfig && agentConfig.type !== 'default') {
 35→    return agentConfig;
 36→  }
 37→
 38→  // Fall back to collection config
 39→  if (collectionConfig && collectionConfig.type !== 'default') {
 40→    return collectionConfig;
 41→  }
 42→
 43→  // System default
 44→  return { type: 'default' };
 45→}
 46→
 47→/**
 48→ * Parse executor config from database JSON
 49→ * Handles null/undefined and validates the shape
 50→ */
 51→export function parseExecutorConfig(
 52→  executorType: string | null | undefined,
 53→  executorConfig: unknown
 54→): ExecutorConfig | null {
 55→  if (!executorType) {
 56→    return null;
 57→  }
 58→
 59→  if (executorType === 'default') {
 60→    return { type: 'default' };
 61→  }
 62→
 63→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 64→    const config = executorConfig as { url?: string; apiKey?: string };
 65→    if (config.url && typeof config.url === 'string') {
 66→      return {
 67→        type: 'custom_url',
 68→        url: config.url,
 69→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 70→      };
 71→    }
 72→  }
 73→
 74→  if (executorType === 'sandbox') {
 75→    const config =
 76→      executorConfig && typeof executorConfig === 'object'
 77→        ? (executorConfig as { url?: string; apiKey?: string })
 78→        : {};
 79→    return {
 80→      type: 'sandbox',
 81→      url: typeof config.url === 'string' ? config.url : undefined,
 82→      apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 83→    };
 84→  }
 85→
 86→  return null;
 87→}
