172→/**
173→ * Create or resume a sandbox session (idempotent)
174→ * If the session already exists, extends its TTL and returns it.
175→ */
176→export async function createSandboxSession(
177→  url: string,
178→  apiKey: string | undefined,
179→  sessionId: string,
180→  timeoutSeconds?: number
181→): Promise<CreateSessionResponse> {
182→  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
183→  if (apiKey) {
184→    headers.Authorization = `Bearer ${apiKey}`;
185→  }
186→
187→  const controller = new AbortController();
188→  const timeoutId = setTimeout(() => controller.abort(), 15000);
189→
190→  try {
191→    const response = await fetch(`${url}/sessions`, {
192→      method: 'POST',
193→      headers,
194→      body: JSON.stringify({ sessionId, timeoutSeconds }),
195→      signal: controller.signal,
196→    });
197→
198→    clearTimeout(timeoutId);
199→
200→    if (!response.ok) {
201→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
202→        error?: string;
203→      };
204→      throw new Error(errorData.error || `Failed to create sandbox session: ${response.status}`);
205→    }
206→
207→    return (await response.json()) as CreateSessionResponse;
208→  } catch (error) {
209→    clearTimeout(timeoutId);
210→    if (error instanceof Error && error.name === 'AbortError') {
211→      throw new Error('Sandbox session creation timed out');
212→    }
213→    throw error;
214→  }
