  1→/**
  2→ * Sandbox Shell Tools for TPMJS Agent Sandbox
  3→ *
  4→ * Execute shell commands, read/write files, and list directories
  5→ * within the stateful sandbox workspace. All paths are resolved
  6→ * relative to `_sandboxWorkDir` (injected by the sandbox server).
  7→ *
  8→ * Runs inside Deno — uses Deno.Command, Deno.readTextFile, etc.
  9→ */
 10→
 11→import { jsonSchema, tool } from 'ai';
 12→
 13→// ---------------------------------------------------------------------------
 14→// Constants
 15→// ---------------------------------------------------------------------------
 16→
 17→const MAX_STDOUT = 100 * 1024; // 100 KB
 18→const MAX_READ_SIZE = 500 * 1024; // 500 KB
 19→const DEFAULT_TIMEOUT_MS = 30_000;
 20→const MAX_TIMEOUT_MS = 300_000;
 21→const MAX_LIST_ENTRIES = 1_000;
 22→const DEFAULT_MAX_DEPTH = 3;
 23→
 24→// ---------------------------------------------------------------------------
 25→// Result types
 26→// ---------------------------------------------------------------------------
 27→
 28→export interface ShellExecResult {
 29→  stdout: string;
 30→  stderr: string;
 31→  exitCode: number;
 32→  durationMs: number;
 33→  truncated: boolean;
 34→}
 35→
 36→export interface ReadFileResult {
 37→  content: string;
 38→  path: string;
 39→  size: number;
 40→  truncated: boolean;
 41→}
 42→
 43→export interface WriteFileResult {
 44→  success: boolean;
 45→  path: string;
 46→  bytesWritten: number;
 47→}
 48→
 49→export interface FileEntry {
 50→  name: string;
 51→  type: 'file' | 'directory' | 'symlink';
 52→  size: number | null;
 53→}
 54→
 55→export interface ListFilesResult {
 56→  path: string;
 57→  entries: FileEntry[];
 58→  truncated: boolean;
 59→}
 60→
 61→// ---------------------------------------------------------------------------
 62→// Helpers
 63→// ---------------------------------------------------------------------------
 64→
 65→function resolveSandboxPath(workDir: string, relativePath: string): string {
 66→  // Normalize: remove leading slash (paths are relative to workDir)
 67→  const cleaned = relativePath.replace(/^\/+/, '');
 68→
 69→  // Simple join — Deno runs on Linux so forward slashes only
 70→  const resolved = `${workDir}/${cleaned}`.replace(/\/+/g, '/');
 71→
 72→  // Security: ensure the resolved path stays inside workDir
 73→  // Normalize away any .. segments by splitting and resolving
 74→  const parts = resolved.split('/');
 75→  const normalized: string[] = [];
 76→  for (const part of parts) {
 77→    if (part === '..') {
 78→      normalized.pop();
 79→    } else if (part !== '.' && part !== '') {
 80→      normalized.push(part);
 81→    }
 82→  }
 83→  const final = '/' + normalized.join('/');
 84→
 85→  const normalizedWorkDir = '/' + workDir.replace(/^\/+/, '').replace(/\/+$/, '');
 86→  if (!final.startsWith(normalizedWorkDir)) {
 87→    throw new Error(`Path escapes sandbox workspace: ${relativePath}`);
 88→  }
 89→
 90→  return final;
 91→}
 92→
 93→function truncate(text: string, maxBytes: number): { text: string; truncated: boolean } {
 94→  const encoder = new TextEncoder();
 95→  const bytes = encoder.encode(text);
 96→  if (bytes.length <= maxBytes) {
 97→    return { text, truncated: false };
 98→  }
 99→  // Truncate at byte boundary, decode back (may lose partial char)
100→  const decoder = new TextDecoder('utf-8', { fatal: false });
101→  return {
102→    text: decoder.decode(bytes.slice(0, maxBytes)) + '\n... [truncated]',
103→    truncated: true,
104→  };
105→}
106→
107→async function collectStream(stream: ReadableStream<Uint8Array>): Promise<Uint8Array> {
108→  const reader = stream.getReader();
109→  const chunks: Uint8Array[] = [];
110→  let totalLength = 0;
111→  while (true) {
112→    const { done, value } = await reader.read();
113→    if (done) break;
114→    chunks.push(value);
115→    totalLength += value.length;
116→  }
117→  const result = new Uint8Array(totalLength);
118→  let offset = 0;
119→  for (const chunk of chunks) {
120→    result.set(chunk, offset);
121→    offset += chunk.length;
122→  }
123→  return result;
124→}
125→
126→// ---------------------------------------------------------------------------
127→// shellExec
128→// ---------------------------------------------------------------------------
129→
130→type ShellExecInput = {
131→  command: string;
132→  timeout?: number;
133→  _sandboxWorkDir?: string;
134→};
135→
136→export const shellExec = tool({
137→  description:
138→    'Execute a shell command in the sandbox workspace. Supports git, npm, and any CLI tools available in the container.',
139→  inputSchema: jsonSchema<ShellExecInput>({
140→    type: 'object',
141→    properties: {
142→      command: {
143→        type: 'string',
144→        description: 'Shell command to execute (passed to sh -c)',
145→      },
146→      timeout: {
147→        type: 'number',
148→        description: 'Timeout in milliseconds (default: 30000, max: 300000)',
149→      },
150→      _sandboxWorkDir: {
151→        type: 'string',
152→        description: 'Injected by sandbox server — workspace directory',
153→      },
154→    },
155→    required: ['command'],
156→    additionalProperties: false,
157→  }),
158→  async execute({ command, timeout, _sandboxWorkDir }) {
159→    if (!_sandboxWorkDir) {
160→      throw new Error('shellExec requires a sandbox session (_sandboxWorkDir not set)');
161→    }
162→
163→    const timeoutMs = Math.min(Math.max(timeout ?? DEFAULT_TIMEOUT_MS, 1000), MAX_TIMEOUT_MS);
164→    const startTime = Date.now();
165→
166→    const cmd = new Deno.Command('sh', {
167→      args: ['-c', command],
168→      cwd: _sandboxWorkDir,
169→      stdout: 'piped',
170→      stderr: 'piped',
171→    });
172→
173→    const child = cmd.spawn();
174→
175→    // Timeout handling — kill the process if it exceeds the limit
176→    let timedOut = false;
177→    const timer = setTimeout(() => {
178→      timedOut = true;
179→      try {
180→        child.kill('SIGKILL');
181→      } catch {
182→        // Process may have already exited
183→      }
184→    }, timeoutMs);
185→
186→    try {
187→      // Collect stdout and stderr concurrently
188→      const [stdoutBytes, stderrBytes, status] = await Promise.all([
189→        collectStream(child.stdout),
190→        collectStream(child.stderr),
191→        child.status,
192→      ]);
193→
194→      clearTimeout(timer);
195→      const durationMs = Date.now() - startTime;
196→      const decoder = new TextDecoder('utf-8', { fatal: false });
197→
198→      const stdoutRaw = decoder.decode(stdoutBytes);
199→      const stderrRaw = decoder.decode(stderrBytes);
200→
201→      const stdout = truncate(stdoutRaw, MAX_STDOUT);
202→      const stderr = truncate(stderrRaw, MAX_STDOUT);
203→
204→      const result: ShellExecResult = {
205→        stdout: stdout.text,
206→        stderr: timedOut ? `[TIMEOUT after ${timeoutMs}ms] ${stderr.text}` : stderr.text,
207→        exitCode: timedOut ? 137 : status.code,
208→        durationMs,
209→        truncated: stdout.truncated || stderr.truncated,
210→      };
211→
212→      return result;
213→    } catch (error) {
214→      clearTimeout(timer);
215→      throw new Error(
216→        `Shell execution failed: ${error instanceof Error ? error.message : String(error)}`,
217→      );
218→    }
219→  },
220→});
221→
222→// ---------------------------------------------------------------------------
223→// readFile
224→// ---------------------------------------------------------------------------
225→
226→type ReadFileInput = {
227→  path: string;
228→  _sandboxWorkDir?: string;
229→};
230→
231→export const readFile = tool({
232→  description: 'Read a file from the sandbox workspace.',
233→  inputSchema: jsonSchema<ReadFileInput>({
234→    type: 'object',
235→    properties: {
236→      path: {
237→        type: 'string',
238→        description: 'File path relative to workspace root',
239→      },
240→      _sandboxWorkDir: {
241→        type: 'string',
242→        description: 'Injected by sandbox server — workspace directory',
243→      },
244→    },
245→    required: ['path'],
246→    additionalProperties: false,
247→  }),
248→  async execute({ path: filePath, _sandboxWorkDir }) {
249→    if (!_sandboxWorkDir) {
250→      throw new Error('readFile requires a sandbox session (_sandboxWorkDir not set)');
251→    }
252→
253→    const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
254→    const content = await Deno.readTextFile(resolved);
255→
256→    const { text, truncated } = truncate(content, MAX_READ_SIZE);
257→
258→    const stat = await Deno.stat(resolved);
259→
260→    const result: ReadFileResult = {
261→      content: text,
262→      path: filePath,
263→      size: stat.size,
264→      truncated,
265→    };
266→
267→    return result;
268→  },
269→});
270→
271→// ---------------------------------------------------------------------------
272→// writeFile
273→// ---------------------------------------------------------------------------
274→
275→type WriteFileInput = {
276→  path: string;
277→  content: string;
278→  createDirs?: boolean;
279→  _sandboxWorkDir?: string;
280→};
281→
282→export const writeFile = tool({
283→  description: 'Write or create a file in the sandbox workspace.',
284→  inputSchema: jsonSchema<WriteFileInput>({
285→    type: 'object',
286→    properties: {
287→      path: {
288→        type: 'string',
289→        description: 'File path relative to workspace root',
290→      },
291→      content: {
292→        type: 'string',
293→        description: 'Content to write to the file',
294→      },
295→      createDirs: {
296→        type: 'boolean',
297→        description: 'Create parent directories if they do not exist (default: true)',
298→      },
299→      _sandboxWorkDir: {
300→        type: 'string',
301→        description: 'Injected by sandbox server — workspace directory',
302→      },
303→    },
304→    required: ['path', 'content'],
305→    additionalProperties: false,
306→  }),
307→  async execute({ path: filePath, content, createDirs = true, _sandboxWorkDir }) {
308→    if (!_sandboxWorkDir) {
309→      throw new Error('writeFile requires a sandbox session (_sandboxWorkDir not set)');
310→    }
311→
312→    const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
313→
314→    // Create parent directories if requested
315→    if (createDirs) {
316→      const parentDir = resolved.substring(0, resolved.lastIndexOf('/'));
317→      if (parentDir) {
318→        await Deno.mkdir(parentDir, { recursive: true });
319→      }
320→    }
321→
322→    await Deno.writeTextFile(resolved, content);
323→
324→    const encoder = new TextEncoder();
325→    const bytesWritten = encoder.encode(content).length;
326→
327→    const result: WriteFileResult = {
328→      success: true,
329→      path: filePath,
330→      bytesWritten,
331→    };
332→
333→    return result;
334→  },
335→});
336→
337→// ---------------------------------------------------------------------------
338→// listFiles
339→// ---------------------------------------------------------------------------
340→
341→type ListFilesInput = {
342→  path?: string;
343→  recursive?: boolean;
344→  maxDepth?: number;
345→  _sandboxWorkDir?: string;
346→};
347→
348→export const listFiles = tool({
349→  description: 'List files and directories in the sandbox workspace.',
350→  inputSchema: jsonSchema<ListFilesInput>({
351→    type: 'object',
352→    properties: {
353→      path: {
354→        type: 'string',
355→        description: 'Directory path relative to workspace root (default: root)',
356→      },
357→      recursive: {
358→        type: 'boolean',
359→        description: 'List recursively (default: false)',
360→      },
361→      maxDepth: {
362→        type: 'number',
363→        description: 'Maximum depth for recursive listing (default: 3)',
364→      },
365→      _sandboxWorkDir: {
366→        type: 'string',
367→        description: 'Injected by sandbox server — workspace directory',
368→      },
369→    },
370→    additionalProperties: false,
371→  }),
372→  async execute({ path: dirPath = '.', recursive = false, maxDepth, _sandboxWorkDir }) {
373→    if (!_sandboxWorkDir) {
374→      throw new Error('listFiles requires a sandbox session (_sandboxWorkDir not set)');
375→    }
376→
377→    const effectiveMaxDepth = maxDepth ?? DEFAULT_MAX_DEPTH;
378→    const resolved = resolveSandboxPath(_sandboxWorkDir, dirPath);
379→    const entries: FileEntry[] = [];
380→    let truncated = false;
381→
382→    async function walk(dir: string, depth: number, prefix: string): Promise<void> {
383→      if (entries.length >= MAX_LIST_ENTRIES) {
384→        truncated = true;
385→        return;
386→      }
387→
388→      for await (const entry of Deno.readDir(dir)) {
389→        if (entries.length >= MAX_LIST_ENTRIES) {
390→          truncated = true;
391→          return;
392→        }
393→
394→        const entryPath = `${dir}/${entry.name}`;
395→        const displayName = prefix ? `${prefix}/${entry.name}` : entry.name;
396→
397→        let size: number | null = null;
398→        if (entry.isFile) {
399→          try {
400→            const info = await Deno.stat(entryPath);
401→            size = info.size;
402→          } catch {
403→            // Permission or race condition — skip size
404→          }
405→        }
406→
407→        entries.push({
408→          name: displayName,
409→          type: entry.isDirectory ? 'directory' : entry.isSymlink ? 'symlink' : 'file',
410→          size,
411→        });
412→
413→        if (recursive && entry.isDirectory && depth < effectiveMaxDepth) {
414→          await walk(entryPath, depth + 1, displayName);
415→        }
416→      }
417→    }
418→
419→    await walk(resolved, 0, '');
420→
421→    const result: ListFilesResult = {
422→      path: dirPath,
423→      entries,
424→      truncated,
425→    };
426→
427→    return result;
428→  },
429→});
430→
431→// ---------------------------------------------------------------------------
432→// Default export
433→// ---------------------------------------------------------------------------
434→
435→export default { shellExec, readFile, writeFile, listFiles };
