 22→/**
 23→ * Check if a tool can be imported (load-and-describe)
 24→ */
 25→async function checkImportHealth(tool: Tool & { package: Package }): Promise<{
 26→  status: HealthStatus;
 27→  error: string | null;
 28→  timeMs: number;
 29→}> {
 30→  const startTime = Date.now();
 31→
 32→  try {
 33→    const response = await fetch(`${RAILWAY_EXECUTOR_URL}/load-and-describe`, {
 34→      method: 'POST',
 35→      headers: { 'Content-Type': 'application/json' },
 36→      body: JSON.stringify({
 37→        packageName: tool.package.npmPackageName,
 38→        name: tool.name,
 39→        version: tool.package.npmVersion,
 40→        env: tool.package.env || {},
 41→      }),
 42→      signal: AbortSignal.timeout(30000), // 30 second timeout
 43→    });
 44→
 45→    const timeMs = Date.now() - startTime;
 46→    const data = await response.json();
 47→
 48→    if (!response.ok || !data.success) {
 49→      const error = data.error || `HTTP ${response.status}`;
 50→
 51→      // If error is config/input issue, tool is not broken
 52→      if (isNonBreakingError(error)) {
 53→        return {
 54→          status: 'HEALTHY',
 55→          error: null,
 56→          timeMs,
 57→        };
 58→      }
 59→
 60→      return {
 61→        status: 'BROKEN',
 62→        error,
 63→        timeMs,
 64→      };
 65→    }
 66→
 67→    // Verify tool has required fields
 68→    if (!data.tool?.description || !data.tool?.inputSchema) {
 69→      return {
 70→        status: 'BROKEN',
 71→        error: 'Missing required tool fields (description or inputSchema)',
 72→        timeMs,
 73→      };
 74→    }
 75→
 76→    return { status: 'HEALTHY', error: null, timeMs };
 77→  } catch (error) {
 78→    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
 79→
 80→    // If error is config/input issue, tool is not broken
 81→    if (isNonBreakingError(errorMessage)) {
 82→      return {
 83→        status: 'HEALTHY',
 84→        error: null,
 85→        timeMs: Date.now() - startTime,
 86→      };
 87→    }
 88→
 89→    return {
 90→      status: 'BROKEN',
 91→      error: errorMessage,
 92→      timeMs: Date.now() - startTime,
