 97→/**
 98→ * Check if a tool can execute with test parameters
 99→ *
100→ * IMPORTANT: If the tool executes at all (even with errors), it's HEALTHY.
101→ * We only mark as BROKEN for infrastructure failures (timeouts, network errors).
102→ * Validation errors mean the tool IS working - it's correctly rejecting bad input.
103→ */
104→async function checkExecutionHealth(tool: Tool & { package: Package }): Promise<{
105→  status: HealthStatus;
106→  error: string | null;
107→  timeMs: number;
108→  testParams: Record<string, unknown>;
109→}> {
110→  const startTime = Date.now();
111→
112→  // Generate test parameters based on tool schema
113→  const testParams = generateTestParameters(tool);
114→
115→  try {
116→    const response = await fetch(`${RAILWAY_EXECUTOR_URL}/execute-tool`, {
117→      method: 'POST',
118→      headers: { 'Content-Type': 'application/json' },
119→      body: JSON.stringify({
120→        packageName: tool.package.npmPackageName,
121→        name: tool.name,
122→        version: tool.package.npmVersion,
123→        params: testParams,
124→        env: tool.package.env || {},
125→      }),
126→      signal: AbortSignal.timeout(30000), // 30 second timeout
127→    });
128→
129→    const timeMs = Date.now() - startTime;
130→
131→    // If we got a response from the executor, the tool executed
132→    // Any error in the response is from the tool itself (validation, env, etc.)
133→    // which means the tool IS working - it's correctly processing/rejecting input
134→    if (response.ok) {
135→      // Executor responded - tool executed (success or tool-level error)
136→      return { status: 'HEALTHY', error: null, timeMs, testParams };
137→    }
138→
139→    // HTTP error from executor - could be tool-level or infrastructure
140→    const data = await response.json().catch(() => ({}));
141→    const error = data.error || `HTTP ${response.status}`;
142→
143→    // Check if this is a config/validation error (tool is working, just missing setup)
144→    // The executor returns 500 for all tool errors, so we need to inspect the message
145→    if (isNonBreakingError(error)) {
146→      return { status: 'HEALTHY', error: null, timeMs, testParams };
147→    }
148→
149→    // True infrastructure failures (executor down, rate limited, etc.)
150→    if (response.status >= 500) {
151→      return { status: 'BROKEN', error, timeMs, testParams };
152→    }
153→
154→    // 4xx errors are likely tool-level validation/config issues
155→    return { status: 'HEALTHY', error: null, timeMs, testParams };
156→  } catch (error) {
157→    // Network/timeout errors are infrastructure issues
158→    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
159→
160→    // Timeout or network error = infrastructure issue = BROKEN
161→    return {
162→      status: 'BROKEN',
163→      error: errorMessage,
164→      timeMs: Date.now() - startTime,
165→      testParams,
166→    };
167→  }
168→}
