170→/**
171→ * Check if an error is due to missing environment variables (configuration issue)
172→ * rather than a broken tool (code issue)
173→ */
174→function isEnvironmentConfigError(error: string | null): boolean {
175→  if (!error) return false;
176→
177→  const envErrorPatterns = [
178→    /is required/i,
179→    /is not set/i,
180→    /missing.*environment/i,
181→    /environment.*missing/i,
182→    /api key.*required/i,
183→    /api key.*not provided/i,
184→    /missing.*api key/i,
185→    /must be set/i,
186→    /not found.*environment/i,
187→    /please set/i,
188→    /please provide/i,
189→    /configure.*environment/i,
190→  ];
191→
192→  return envErrorPatterns.some((pattern) => pattern.test(error));
193→}
194→
195→/**
196→ * Check if an error is due to input validation (Zod validation, URL format, etc.)
197→ * These errors mean the tool is working correctly - it's validating input as expected
198→ */
199→function isInputValidationError(error: string | null): boolean {
200→  if (!error) return false;
201→
202→  const validationErrorPatterns = [
203→    /must have a valid.*domain/i, // URL validation
204→    /valid.*path/i, // Path validation
205→    /invalid.*url/i, // URL format
206→    /invalid.*format/i, // General format validation
207→    /expected.*received/i, // Zod type errors
208→    /must be.*string/i, // Type validation
209→    /must be.*number/i,
210→    /must be.*boolean/i,
211→    /must be.*array/i,
212→    /must be.*object/i,
213→    /validation.*failed/i, // General validation
214→    /does not match/i, // Pattern/regex validation
215→    /too short/i, // Length validation
216→    /too long/i,
217→    /minimum.*length/i,
218→    /maximum.*length/i,
219→  ];
220→
221→  return validationErrorPatterns.some((pattern) => pattern.test(error));
222→}
223→
224→/**
225→ * Check if an error is a configuration or input issue (not a broken tool)
226→ */
227→function isNonBreakingError(error: string | null): boolean {
228→  return isEnvironmentConfigError(error) || isInputValidationError(error);
229→}
