235→function generateTestParameters(tool: Tool & { package: Package }): Record<string, unknown> {
236→  const parameters = Array.isArray(tool.parameters)
237→    ? (tool.parameters as Array<{ name: string; type: string; required: boolean }>)
238→    : [];
