240→  const testParams: Record<string, unknown> = {};
241→
242→  for (const param of parameters) {
243→    if (param.required) {
244→      // Generate minimal test value based on type
245→      switch (param.type) {
246→        case 'string':
247→          testParams[param.name] = 'test';
248→          break;
249→        case 'number':
250→          testParams[param.name] = 1;
251→          break;
252→        case 'boolean':
253→          testParams[param.name] = true;
254→          break;
255→        case 'object':
256→          testParams[param.name] = {};
257→          break;
258→        case 'array':
259→          testParams[param.name] = [];
260→          break;
261→        default:
262→          testParams[param.name] = 'test';
263→      }
264→    }
