  1→/**
  2→ * Executor Resolution Logic
  3→ *
  4→ * Handles the cascade resolution for hot-swappable executors:
  5→ * Agent Config → Collection Config → System Default
  6→ */
  7→
  8→import { executePackage } from '@tpmjs/package-executor';
  9→import type {
 10→  CreateSessionResponse,
 11→  DestroySessionResponse,
 12→  ExecuteToolRequest,
 13→  ExecuteToolResponse,
 14→  ExecutorConfig,
 15→  ExecutorHealthResponse,
 16→  SandboxExecutorConfig,
 17→} from '@tpmjs/types/executor';
 18→
 19→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
 20→
 21→/**
 22→ * Resolve executor configuration using cascade:
 23→ * Agent Config → Collection Config → System Default
 24→ *
 25→ * @param agentConfig - Executor config from Agent (highest priority)
 26→ * @param collectionConfig - Executor config from Collection (medium priority)
 27→ * @returns Resolved executor configuration
 28→ */
 29→export function resolveExecutorConfig(
 30→  agentConfig: ExecutorConfig | null | undefined,
 31→  collectionConfig: ExecutorConfig | null | undefined
 32→): ExecutorConfig {
 33→  // Agent config takes precedence
 34→  if (agentConfig && agentConfig.type !== 'default') {
 35→    return agentConfig;
 36→  }
 37→
 38→  // Fall back to collection config
 39→  if (collectionConfig && collectionConfig.type !== 'default') {
 40→    return collectionConfig;
 41→  }
 42→
 43→  // System default
 44→  return { type: 'default' };
 45→}
 46→
 47→/**
 48→ * Parse executor config from database JSON
 49→ * Handles null/undefined and validates the shape
 50→ */
 51→export function parseExecutorConfig(
 52→  executorType: string | null | undefined,
 53→  executorConfig: unknown
 54→): ExecutorConfig | null {
 55→  if (!executorType) {
 56→    return null;
 57→  }
 58→
 59→  if (executorType === 'default') {
 60→    return { type: 'default' };
 61→  }
 62→
 63→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
 64→    const config = executorConfig as { url?: string; apiKey?: string };
 65→    if (config.url && typeof config.url === 'string') {
 66→      return {
 67→        type: 'custom_url',
 68→        url: config.url,
 69→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 70→      };
 71→    }
 72→  }
 73→
 74→  if (executorType === 'sandbox') {
 75→    const config =
 76→      executorConfig && typeof executorConfig === 'object'
 77→        ? (executorConfig as { url?: string; apiKey?: string })
 78→        : {};
 79→    return {
 80→      type: 'sandbox',
 81→      url: typeof config.url === 'string' ? config.url : undefined,
 82→      apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
 83→    };
 84→  }
 85→
 86→  return null;
 87→}
 88→
 89→/**
 90→ * Execute a tool using a custom URL executor
 91→ */
 92→async function executeWithCustomUrl(
 93→  url: string,
 94→  apiKey: string | undefined,
 95→  request: ExecuteToolRequest,
 96→  timeout: number = DEFAULT_TIMEOUT
 97→): Promise<ExecuteToolResponse> {
 98→  const startTime = Date.now();
 99→
100→  const headers: Record<string, string> = {
101→    'Content-Type': 'application/json',
102→  };
103→
104→  if (apiKey) {
105→    headers.Authorization = `Bearer ${apiKey}`;
106→  }
107→
108→  try {
109→    const controller = new AbortController();
110→    const timeoutId = setTimeout(() => controller.abort(), timeout);
111→
112→    const response = await fetch(`${url}/execute-tool`, {
113→      method: 'POST',
114→      headers,
115→      body: JSON.stringify(request),
116→      signal: controller.signal,
117→    });
118→
119→    clearTimeout(timeoutId);
120→
121→    const executionTimeMs = Date.now() - startTime;
122→
123→    if (!response.ok) {
124→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
125→        error?: string;
126→      };
127→      return {
128→        success: false,
129→        error: errorData.error || `Executor error: ${response.status}`,
130→        executionTimeMs,
131→      };
132→    }
133→
134→    const result = (await response.json()) as ExecuteToolResponse;
135→
136→    return {
137→      success: result.success,
138→      output: result.output,
139→      error: result.error,
140→      executionTimeMs: result.executionTimeMs || executionTimeMs,
141→    };
142→  } catch (error) {
143→    const executionTimeMs = Date.now() - startTime;
144→
145→    if (error instanceof Error && error.name === 'AbortError') {
146→      return {
147→        success: false,
148→        error: 'Execution timeout',
149→        executionTimeMs,
150→      };
151→    }
152→
153→    return {
154→      success: false,
155→      error: error instanceof Error ? error.message : String(error),
156→      executionTimeMs,
157→    };
158→  }
159→}
160→
161→// =============================================================================
162→// Sandbox Session Management
163→// =============================================================================
164→
165→/**
166→ * Resolve sandbox URL from config or environment variable
167→ */
168→export function resolveSandboxUrl(config: SandboxExecutorConfig): string | null {
169→  return config.url || process.env.AGENT_SANDBOX_URL || null;
170→}
171→
172→/**
173→ * Create or resume a sandbox session (idempotent)
174→ * If the session already exists, extends its TTL and returns it.
175→ */
176→export async function createSandboxSession(
177→  url: string,
178→  apiKey: string | undefined,
179→  sessionId: string,
180→  timeoutSeconds?: number
181→): Promise<CreateSessionResponse> {
182→  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
183→  if (apiKey) {
184→    headers.Authorization = `Bearer ${apiKey}`;
185→  }
186→
187→  const controller = new AbortController();
188→  const timeoutId = setTimeout(() => controller.abort(), 15000);
189→
190→  try {
191→    const response = await fetch(`${url}/sessions`, {
192→      method: 'POST',
193→      headers,
194→      body: JSON.stringify({ sessionId, timeoutSeconds }),
195→      signal: controller.signal,
196→    });
197→
198→    clearTimeout(timeoutId);
199→
200→    if (!response.ok) {
201→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
202→        error?: string;
203→      };
204→      throw new Error(errorData.error || `Failed to create sandbox session: ${response.status}`);
205→    }
206→
207→    return (await response.json()) as CreateSessionResponse;
208→  } catch (error) {
209→    clearTimeout(timeoutId);
210→    if (error instanceof Error && error.name === 'AbortError') {
211→      throw new Error('Sandbox session creation timed out');
212→    }
213→    throw error;
214→  }
215→}
216→
217→/**
218→ * Destroy a sandbox session (fire-and-forget safe)
219→ * Returns gracefully even if the session doesn't exist.
220→ */
221→export async function destroySandboxSession(
222→  url: string,
223→  apiKey: string | undefined,
224→  sessionId: string
225→): Promise<DestroySessionResponse> {
226→  const headers: Record<string, string> = {};
227→  if (apiKey) {
228→    headers.Authorization = `Bearer ${apiKey}`;
229→  }
230→
231→  try {
232→    const controller = new AbortController();
233→    const timeoutId = setTimeout(() => controller.abort(), 10000);
234→
235→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
236→      method: 'DELETE',
237→      headers,
238→      signal: controller.signal,
239→    });
240→
241→    clearTimeout(timeoutId);
242→
243→    if (!response.ok && response.status !== 404) {
244→      return { sessionId, destroyed: false };
245→    }
246→
247→    return (await response
248→      .json()
249→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
250→  } catch {
251→    // Fire-and-forget: don't throw on cleanup failures
252→    return { sessionId, destroyed: false };
253→  }
254→}
255→
256→/**
257→ * Execute a tool using a sandbox executor (includes sessionId in request)
258→ */
259→async function executeWithSandbox(
260→  url: string,
261→  apiKey: string | undefined,
262→  request: ExecuteToolRequest,
263→  sessionId: string,
264→  timeout: number = DEFAULT_TIMEOUT
265→): Promise<ExecuteToolResponse> {
266→  const startTime = Date.now();
267→
268→  const headers: Record<string, string> = {
269→    'Content-Type': 'application/json',
270→  };
271→
272→  if (apiKey) {
273→    headers.Authorization = `Bearer ${apiKey}`;
274→  }
275→
276→  try {
277→    const controller = new AbortController();
278→    const timeoutId = setTimeout(() => controller.abort(), timeout);
279→
280→    const response = await fetch(`${url}/execute-tool`, {
281→      method: 'POST',
282→      headers,
283→      body: JSON.stringify({ ...request, sessionId }),
284→      signal: controller.signal,
285→    });
286→
287→    clearTimeout(timeoutId);
288→
289→    const executionTimeMs = Date.now() - startTime;
290→
291→    if (!response.ok) {
292→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
293→        error?: string;
294→      };
295→      return {
296→        success: false,
297→        error: errorData.error || `Sandbox executor error: ${response.status}`,
298→        executionTimeMs,
299→      };
300→    }
301→
302→    const result = (await response.json()) as ExecuteToolResponse;
303→
304→    return {
305→      success: result.success,
306→      output: result.output,
307→      error: result.error,
308→      executionTimeMs: result.executionTimeMs || executionTimeMs,
309→    };
310→  } catch (error) {
311→    const executionTimeMs = Date.now() - startTime;
312→
313→    if (error instanceof Error && error.name === 'AbortError') {
314→      return {
315→        success: false,
316→        error: 'Execution timeout',
317→        executionTimeMs,
318→      };
319→    }
320→
321→    return {
322→      success: false,
323→      error: error instanceof Error ? error.message : String(error),
324→      executionTimeMs,
325→    };
326→  }
327→}
328→
329→/**
330→ * Execute a tool using the resolved executor configuration
331→ *
332→ * @param config - Resolved executor config (or null for default)
333→ * @param request - Tool execution request
334→ * @param sessionId - Optional session ID for sandbox executors
335→ * @returns Execution result
336→ */
337→export async function executeWithExecutor(
338→  config: ExecutorConfig | null,
339→  request: ExecuteToolRequest,
340→  sessionId?: string
341→): Promise<ExecuteToolResponse> {
342→  const resolvedConfig = config ?? { type: 'default' };
343→
344→  // Use custom URL executor
345→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
346→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
347→  }
348→
349→  // Use sandbox executor
350→  if (resolvedConfig.type === 'sandbox' && sessionId) {
351→    const sandboxUrl = resolveSandboxUrl(resolvedConfig);
352→    if (!sandboxUrl) {
353→      return {
354→        success: false,
355→        error:
356→          'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom URL.',
357→        executionTimeMs: 0,
358→      };
359→    }
360→    return executeWithSandbox(sandboxUrl, resolvedConfig.apiKey, request, sessionId);
361→  }
362→
363→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
364→  const result = await executePackage(request.packageName, request.name, request.params, {
365→    env: request.env,
366→    version: request.version,
367→  });
368→
369→  return {
370→    success: result.success,
371→    output: result.output,
372→    error: result.error,
373→    executionTimeMs: result.executionTimeMs,
374→  };
375→}
376→
377→/**
378→ * Check the health of a custom executor URL
379→ *
380→ * @param url - Executor URL to check
381→ * @param apiKey - Optional API key for authentication
382→ * @returns Health check response or error
383→ */
384→export async function checkExecutorHealth(
385→  url: string,
386→  apiKey?: string
387→): Promise<{ healthy: boolean; response?: ExecutorHealthResponse; error?: string }> {
388→  const headers: Record<string, string> = {};
389→
390→  if (apiKey) {
391→    headers.Authorization = `Bearer ${apiKey}`;
392→  }
393→
394→  try {
395→    const controller = new AbortController();
396→    const timeoutId = setTimeout(() => controller.abort(), 10000); // 10 second timeout for health checks
397→
398→    const response = await fetch(`${url}/health`, {
399→      method: 'GET',
400→      headers,
401→      signal: controller.signal,
402→    });
403→
404→    clearTimeout(timeoutId);
405→
406→    if (!response.ok) {
407→      return {
408→        healthy: false,
409→        error: `Health check failed: ${response.status}`,
410→      };
411→    }
412→
413→    const data = (await response.json()) as ExecutorHealthResponse;
414→
415→    return {
416→      healthy: data.status === 'ok' || data.status === 'degraded',
417→      response: data,
418→    };
419→  } catch (error) {
420→    if (error instanceof Error && error.name === 'AbortError') {
421→      return {
422→        healthy: false,
423→        error: 'Health check timeout',
424→      };
425→    }
426→
427→    return {
428→      healthy: false,
429→      error: error instanceof Error ? error.message : 'Unknown error',
430→    };
431→  }
432→}
433→
434→/**
435→ * Test a custom executor by running a simple tool execution
436→ *
437→ * @param url - Executor URL to test
438→ * @param apiKey - Optional API key for authentication
439→ * @returns Test execution result
440→ */
441→export async function testExecutor(
442→  url: string,
443→  apiKey?: string
444→): Promise<{ success: boolean; executionTimeMs: number; error?: string }> {
445→  const testRequest: ExecuteToolRequest = {
446→    packageName: '@tpmjs/hello',
447→    name: 'helloWorldTool',
448→    version: '0.0.2',
449→    params: { includeTimestamp: true },
450→  };
451→
452→  const result = await executeWithCustomUrl(url, apiKey, testRequest, 30000); // 30 second timeout for test (includes npm install)
453→
454→  return {
455→    success: result.success,
456→    executionTimeMs: result.executionTimeMs,
457→    error: result.error,
458→  };
459→}
460→
461→/**
462→ * Verify a custom executor URL is valid and operational
463→ *
464→ * @param url - Executor URL to verify
465→ * @param apiKey - Optional API key for authentication
466→ * @returns Verification result
467→ */
468→export async function verifyExecutor(
469→  url: string,
470→  apiKey?: string
471→): Promise<{
472→  valid: boolean;
473→  healthCheck?: { healthy: boolean; response?: ExecutorHealthResponse };
474→  testExecution?: { success: boolean; executionTimeMs: number };
475→  errors: string[];
476→}> {
477→  const errors: string[] = [];
478→
479→  // Validate URL format
480→  try {
481→    const parsed = new URL(url);
482→    if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
483→      errors.push('Custom executor URL must use HTTPS in production');
484→    }
485→  } catch {
486→    errors.push('Invalid URL format');
487→    return { valid: false, errors };
488→  }
489→
490→  // Check health endpoint
491→  const healthResult = await checkExecutorHealth(url, apiKey);
492→  if (!healthResult.healthy) {
493→    errors.push(healthResult.error || 'Health check failed');
494→  }
495→
496→  // Test execution (only if health check passed)
497→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
498→  if (healthResult.healthy) {
499→    const execResult = await testExecutor(url, apiKey);
500→    testResult = {
501→      success: execResult.success,
