            resourceType: 'agent',
            resourceId: agent.id,
            tokensIn: inputTokens,
            tokensOut: outputTokens,
            model: agent.modelId,
          });
        }
      } catch (error) {
        // Log detailed error for debugging
        console.error('[Agent] Conversation stream error:', {
