342→  path?: string;
343→  recursive?: boolean;
344→  maxDepth?: number;
345→  _sandboxWorkDir?: string;
346→};
347→
348→export const listFiles = tool({
349→  description: 'List files and directories in the sandbox workspace.',
350→  inputSchema: jsonSchema<ListFilesInput>({
351→    type: 'object',
352→    properties: {
353→      path: {
354→        type: 'string',
355→        description: 'Directory path relative to workspace root (default: root)',
356→      },
357→      recursive: {
358→        type: 'boolean',
359→        description: 'List recursively (default: false)',
360→      },
361→      maxDepth: {
362→        type: 'number',
363→        description: 'Maximum depth for recursive listing (default: 3)',
364→      },
365→      _sandboxWorkDir: {
366→        type: 'string',
367→        description: 'Injected by sandbox server — workspace directory',
368→      },
369→    },
370→    additionalProperties: false,
371→  }),
372→  async execute({ path: dirPath = '.', recursive = false, maxDepth, _sandboxWorkDir }) {
373→    if (!_sandboxWorkDir) {
374→      throw new Error('listFiles requires a sandbox session (_sandboxWorkDir not set)');
375→    }
376→
377→    const effectiveMaxDepth = maxDepth ?? DEFAULT_MAX_DEPTH;
378→    const resolved = resolveSandboxPath(_sandboxWorkDir, dirPath);
379→    const entries: FileEntry[] = [];
380→    let truncated = false;
381→
382→    async function walk(dir: string, depth: number, prefix: string): Promise<void> {
383→      if (entries.length >= MAX_LIST_ENTRIES) {
384→        truncated = true;
385→        return;
386→      }
387→
388→      for await (const entry of Deno.readDir(dir)) {
389→        if (entries.length >= MAX_LIST_ENTRIES) {
390→          truncated = true;
391→          return;
392→        }
393→
394→        const entryPath = `${dir}/${entry.name}`;
395→        const displayName = prefix ? `${prefix}/${entry.name}` : entry.name;
396→
397→        let size: number | null = null;
398→        if (entry.isFile) {
399→          try {
400→            const info = await Deno.stat(entryPath);
401→            size = info.size;
402→          } catch {
403→            // Permission or race condition — skip size
404→          }
405→        }
406→
407→        entries.push({
408→          name: displayName,
409→          type: entry.isDirectory ? 'directory' : entry.isSymlink ? 'symlink' : 'file',
410→          size,
411→        });
412→
413→        if (recursive && entry.isDirectory && depth < effectiveMaxDepth) {
414→          await walk(entryPath, depth + 1, displayName);
415→        }
416→      }
417→    }
418→
419→    await walk(resolved, 0, '');
420→
421→    const result: ListFilesResult = {
422→      path: dirPath,
423→      entries,
424→      truncated,
425→    };
426→
427→    return result;
428→  },
429→});
430→
431→// ---------------------------------------------------------------------------
432→// Default export
433→// ---------------------------------------------------------------------------
434→
435→export default { shellExec, readFile, writeFile, listFiles };
