async function executeWithSandbox(
  url: string,
  apiKey: string | undefined,
  request: ExecuteToolRequest,
  sessionId: string,
  timeout: number = DEFAULT_TIMEOUT
): Promise<ExecuteToolResponse> {
  const startTime = Date.now();

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  if (apiKey) {
    headers.Authorization = `Bearer ${apiKey}`;
  }

  // Retry on transient failures (network errors, 429, 502, 503)
  let lastError: unknown;
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeout);

      const response = await fetch(`${url}/execute-tool`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ ...request, sessionId }),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      const executionTimeMs = Date.now() - startTime;

      // Retry on 429 (capacity) or 502/503 (transient server issues)
      if ((response.status === 429 || response.status === 502 || response.status === 503) && attempt < MAX_RETRIES) {
        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
        console.warn(`[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`);
        await new Promise((resolve) => setTimeout(resolve, delay));
        continue;
      }

      if (!response.ok) {
        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
          error?: string;
        };
        return {
          success: false,
          error: errorData.error || `Sandbox executor error: ${response.status}`,
          executionTimeMs,
        };
      }

      const result = (await response.json()) as ExecuteToolResponse;

      return {
        success: result.success,
        output: result.output,
        error: result.error,
        executionTimeMs: result.executionTimeMs || executionTimeMs,
      };
    } catch (error) {
      lastError = error;

      if (error instanceof Error && error.name === 'AbortError') {
        return {
          success: false,
          error: 'Execution timeout',
          executionTimeMs: Date.now() - startTime,
        };
      }

      // Retry on network errors
      if (attempt < MAX_RETRIES) {
        const msg = error instanceof Error ? error.message : String(error);
        if (msg.includes('ECONNREFUSED') || msg.includes('fetch failed') || msg.includes('ECONNRESET')) {
          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
          console.warn(`[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`, msg);
          await new Promise((resolve) => setTimeout(resolve, delay));
          continue;
        }
      }

      return {
        success: false,
        error: error instanceof Error ? error.message : String(error),
        executionTimeMs: Date.now() - startTime,
      };
    }
  }

  return {
    success: false,
    error: lastError instanceof Error ? lastError.message : String(lastError),
    executionTimeMs: Date.now() - startTime,
  };
}

