setInterval(cleanupExpiredSessions, 60 * 1000);

// ─── Module Cache ───────────────────────────────────────────────────────────

function getCachedModule(cacheKey: string): CacheEntry | null {
  const entry = moduleCache.get(cacheKey);
  if (!entry) return null;
  if (Date.now() > entry.expiresAt) {
