130→/**
131→ * PATCH /api/agents/[id]
132→ * Update an agent's configuration
133→ */
134→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: large PATCH handler with many optional fields
135→export async function PATCH(request: NextRequest, context: RouteContext) {
136→  const requestId = crypto.randomUUID();
137→
138→  try {
139→    const authResult = await authenticateRequest();
140→    if (!authResult.authenticated || !authResult.userId) {
141→      return apiUnauthorized('Authentication required', requestId);
142→    }
143→
144→    const { id } = await context.params;
145→    const body = await request.json();
146→    const parsed = UpdateAgentSchema.safeParse(body);
147→    if (!parsed.success) {
148→      return apiValidationError(
149→        'Invalid request body',
150→        { errors: parsed.error.flatten().fieldErrors },
151→        requestId
152→      );
153→    }
154→
155→    // Check ownership
156→    const existing = await prisma.agent.findUnique({
157→      where: { id },
158→      select: { userId: true },
159→    });
160→    if (!existing) {
161→      return apiNotFound('Agent', requestId);
162→    }
163→    if (existing.userId !== authResult.userId) {
164→      return apiForbidden('Access denied', requestId);
165→    }
166→
167→    // Check UID uniqueness if being changed
168→    if (parsed.data.uid) {
169→      const existingByUid = await prisma.agent.findFirst({
170→        where: { uid: parsed.data.uid, id: { not: id } },
171→      });
172→      if (existingByUid) {
173→        return apiConflict('UID already in use', requestId);
174→      }
175→    }
176→
177→    // Check name uniqueness if being changed
178→    if (parsed.data.name) {
179→      const existingByName = await prisma.agent.findFirst({
180→        where: { userId: authResult.userId, name: parsed.data.name, id: { not: id } },
181→      });
182→      if (existingByName) {
183→        return apiConflict('An agent with this name already exists', requestId);
184→      }
185→    }
186→
187→    // Build update data, transforming JSON fields for Prisma (null -> Prisma.JsonNull)
188→    const { executorConfig, envVars, ...restData } = parsed.data;
189→    const updateData: Prisma.AgentUpdateInput = {
190→      ...restData,
191→      ...(executorConfig !== undefined && {
192→        executorConfig: executorConfig === null ? Prisma.JsonNull : executorConfig,
193→      }),
194→      ...(envVars !== undefined && {
195→        envVars: envVars === null ? Prisma.JsonNull : envVars,
196→      }),
197→    };
198→
199→    const agent = await prisma.agent.update({
200→      where: { id },
201→      data: updateData,
202→      include: {
203→        _count: {
204→          select: {
205→            tools: true,
206→            collections: true,
207→          },
208→        },
209→      },
210→    });
211→
212→    // Log activity (fire-and-forget)
213→    const hasConfigChange =
214→      parsed.data.modelId !== undefined ||
215→      parsed.data.temperature !== undefined ||
216→      parsed.data.systemPrompt !== undefined ||
217→      parsed.data.provider !== undefined;
218→    logActivity({
219→      userId: authResult.userId,
220→      type: hasConfigChange ? 'AGENT_CONFIG_UPDATED' : 'AGENT_UPDATED',
221→      targetName: agent.name,
222→      targetType: 'agent',
223→      agentId: agent.id,
224→    });
225→
226→    return apiSuccess(
227→      {
228→        ...agent,
229→        toolCount: agent._count.tools,
230→        collectionCount: agent._count.collections,
231→        _count: undefined,
232→      },
233→      { requestId }
234→    );
235→  } catch (error) {
236→    console.error('Failed to update agent:', error);
237→    return apiInternalError('Failed to update agent', requestId);
238→  }
239→}
