 82→/**
 83→ * POST /api/agents/[id]/tools
 84→ * Add an individual tool to an agent
 85→ */
 86→export async function POST(request: NextRequest, context: RouteContext): Promise<NextResponse> {
 87→  try {
 88→    const session = await auth.api.getSession({ headers: await headers() });
 89→    if (!session?.user?.id) {
 90→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 91→    }
 92→
 93→    const { id } = await context.params;
 94→    const body = await request.json();
 95→    const parsed = AddToolToAgentSchema.safeParse(body);
 96→    if (!parsed.success) {
 97→      return NextResponse.json(
 98→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
 99→        { status: 400 }
100→      );
101→    }
102→
103→    // Check agent ownership
104→    const agent = await prisma.agent.findUnique({
105→      where: { id },
106→      select: { userId: true, name: true, _count: { select: { tools: true } } },
107→    });
108→    if (!agent) {
109→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
110→    }
111→    if (agent.userId !== session.user.id) {
112→      return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
113→    }
114→
115→    // Check tool limit
116→    if (agent._count.tools >= AGENT_LIMITS.MAX_TOOLS_PER_AGENT) {
117→      return NextResponse.json(
118→        { success: false, error: `Maximum ${AGENT_LIMITS.MAX_TOOLS_PER_AGENT} tools per agent` },
119→        { status: 400 }
120→      );
121→    }
122→
123→    // Check tool exists
124→    const tool = await prisma.tool.findUnique({
125→      where: { id: parsed.data.toolId },
126→      select: {
127→        id: true,
128→        name: true,
129→        description: true,
130→        package: { select: { npmPackageName: true, category: true } },
131→      },
132→    });
133→    if (!tool) {
134→      return NextResponse.json({ success: false, error: 'Tool not found' }, { status: 404 });
135→    }
136→
137→    // Check if already added
138→    const existing = await prisma.agentTool.findUnique({
139→      where: {
140→        agentId_toolId: { agentId: id, toolId: parsed.data.toolId },
141→      },
142→    });
143→    if (existing) {
144→      return NextResponse.json(
145→        { success: false, error: 'Tool already added to agent' },
146→        { status: 409 }
147→      );
148→    }
149→
150→    // Get next position
151→    const maxPosition = await prisma.agentTool.aggregate({
152→      where: { agentId: id },
153→      _max: { position: true },
154→    });
155→    const position = parsed.data.position ?? (maxPosition._max.position ?? -1) + 1;
156→
157→    const agentTool = await prisma.agentTool.create({
158→      data: {
159→        agentId: id,
160→        toolId: parsed.data.toolId,
161→        position,
162→      },
163→      include: {
164→        tool: {
165→          select: {
166→            id: true,
167→            name: true,
168→            description: true,
169→            package: { select: { npmPackageName: true, category: true } },
170→          },
171→        },
172→      },
173→    });
174→
175→    // Log activity (fire-and-forget)
176→    logActivity({
177→      userId: session.user.id,
178→      type: 'AGENT_TOOL_ADDED',
179→      targetName: agent.name,
180→      targetType: 'agent',
181→      agentId: id,
182→      toolId: agentTool.toolId,
183→      metadata: { toolName: agentTool.tool.name },
184→    });
185→
186→    return NextResponse.json(
187→      {
188→        success: true,
189→        data: {
190→          id: agentTool.id,
191→          toolId: agentTool.toolId,
192→          position: agentTool.position,
193→          addedAt: agentTool.addedAt,
194→          tool: agentTool.tool,
195→        },
196→      },
197→      { status: 201 }
198→    );
199→  } catch (error) {
200→    console.error('Failed to add tool to agent:', error);
201→    return NextResponse.json({ success: false, error: 'Failed to add tool' }, { status: 500 });
202→  }
203→}
