  2→ * Executor API Types
  3→ *
  4→ * These types define the contract between TPMJS and any executor service.
  5→ * Custom executors must implement the ExecuteToolRequest/Response interface.
  6→ */
  7→
  8→import { z } from 'zod';
  9→
 10→// =============================================================================
 11→// Executor API Specification
 12→// =============================================================================
 13→
 14→/**
 15→ * Request payload for POST /execute-tool
 16→ */
 17→export interface ExecuteToolRequest {
 18→  /** NPM package name, e.g., "@tpmjs/hello" */
 19→  packageName: string;
 20→  /** Tool name within the package, e.g., "helloWorld" */
 21→  name: string;
 22→  /** Package version, e.g., "1.0.0" or "latest" */
 23→  version?: string;
 24→  /** Direct esm.sh URL override for the package */
 25→  importUrl?: string;
 26→  /** Tool parameters to pass to execute() */
 27→  params: Record<string, unknown>;
 28→  /** Environment variables to inject during execution */
 29→  env?: Record<string, string>;
 30→}
 31→
 32→/**
 33→ * Response from POST /execute-tool
 34→ */
 35→export interface ExecuteToolResponse {
 36→  /** Whether the execution succeeded */
 37→  success: boolean;
 38→  /** Tool output on success */
 39→  output?: unknown;
 40→  /** Error message on failure */
 41→  error?: string;
 42→  /** Execution duration in milliseconds */
 43→  executionTimeMs: number;
 44→}
 45→
 46→/**
 47→ * Response from GET /health (optional but recommended)
 48→ */
 49→export interface ExecutorHealthResponse {
 50→  /** Executor status */
 51→  status: 'ok' | 'degraded' | 'error';
 52→  /** Executor version string */
 53→  version?: string;
 54→  /** Optional additional info */
 55→  info?: Record<string, unknown>;
 56→}
 57→
 58→// =============================================================================
 59→// Executor Configuration Schemas
 60→// =============================================================================
 61→
 62→/**
 63→ * Executor type enum
 64→ */
 65→export const ExecutorTypeSchema = z.enum(['default', 'custom_url', 'sandbox']);
 66→export type ExecutorType = z.infer<typeof ExecutorTypeSchema>;
 67→
 68→/**
 69→ * Default executor config (uses TPMJS Railway executor)
 70→ */
 71→export const DefaultExecutorConfigSchema = z.object({
 72→  type: z.literal('default'),
 73→});
 74→
 75→/**
 76→ * Custom URL executor config
 77→ */
 78→export const CustomUrlExecutorConfigSchema = z.object({
 79→  type: z.literal('custom_url'),
 80→  /** URL of the custom executor (must be HTTPS in production) */
 81→  url: z.string().url(),
 82→  /** Optional API key for Bearer token authentication */
 83→  apiKey: z.string().optional(),
 84→});
 85→
 86→/**
 87→ * Sandbox executor config (stateful sessions with persistent filesystem)
 88→ */
 89→export const SandboxExecutorConfigSchema = z.object({
 90→  type: z.literal('sandbox'),
 91→  /** Optional URL of the sandbox executor (falls back to AGENT_SANDBOX_URL env var) */
 92→  url: z.string().url().optional(),
 93→  /** Optional API key for Bearer token authentication */
 94→  apiKey: z.string().optional(),
 95→});
 96→
 97→/**
 98→ * Union of all executor config types
 99→ */
100→export const ExecutorConfigSchema = z.discriminatedUnion('type', [
101→  DefaultExecutorConfigSchema,
102→  CustomUrlExecutorConfigSchema,
103→  SandboxExecutorConfigSchema,
104→]);
105→
106→export type ExecutorConfig = z.infer<typeof ExecutorConfigSchema>;
107→export type DefaultExecutorConfig = z.infer<typeof DefaultExecutorConfigSchema>;
108→export type CustomUrlExecutorConfig = z.infer<typeof CustomUrlExecutorConfigSchema>;
109→export type SandboxExecutorConfig = z.infer<typeof SandboxExecutorConfigSchema>;
110→
111→// =============================================================================
112→// Zod Schemas for Request/Response Validation
113→// =============================================================================
114→
115→export const ExecuteToolRequestSchema = z.object({
116→  packageName: z.string().min(1),
117→  name: z.string().min(1),
118→  version: z.string().optional(),
119→  importUrl: z.string().url().optional(),
120→  params: z.record(z.string(), z.unknown()),
121→  env: z.record(z.string(), z.string()).optional(),
122→});
123→
124→export const ExecuteToolResponseSchema = z.object({
125→  success: z.boolean(),
126→  output: z.unknown().optional(),
127→  error: z.string().optional(),
128→  executionTimeMs: z.number(),
129→});
130→
131→export const ExecutorHealthResponseSchema = z.object({
132→  status: z.enum(['ok', 'degraded', 'error']),
133→  version: z.string().optional(),
134→  info: z.record(z.string(), z.unknown()).optional(),
135→});
136→
137→// =============================================================================
138→// Executor Verification
139→// =============================================================================
140→
141→export const VerifyExecutorRequestSchema = z.object({
142→  url: z.string().url(),
143→  apiKey: z.string().optional(),
144→});
