/**
 * Create a "Dev Sandbox" agent for thomasalwyndavis@gmail.com
 * with sandbox-shell tools (shellExec, readFile, writeFile, listFiles)
 *
 * Usage: cd packages/db && npx tsx scripts/create-sandbox-agent.ts
 */

import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function main() {
  // 1. Find the user
  const user = await prisma.user.findFirst({
    where: { email: 'thomasalwyndavis@gmail.com' },
    select: { id: true, email: true, username: true },
  });

  if (!user) {
    console.error('User thomasalwyndavis@gmail.com not found');
    process.exit(1);
  }
  console.log(`Found user: ${user.username} (${user.id})`);

  // 2. Find the sandbox-shell package & tools
  const pkg = await prisma.package.findFirst({
    where: { npmPackageName: '@tpmjs/official-sandbox-shell' },
    select: { id: true, npmPackageName: true },
  });

  let toolIds: string[] = [];

  if (pkg) {
    const tools = await prisma.tool.findMany({
      where: { packageId: pkg.id },
      select: { id: true, name: true, slug: true },
    });
    console.log(
      `Found ${tools.length} sandbox-shell tools:`,
      tools.map((t) => t.name)
    );
    toolIds = tools.map((t) => t.id);
  } else {
    console.warn(
      'Package @tpmjs/official-sandbox-shell not found in DB — agent will be created without tools.'
    );
    console.warn('Run `pnpm sync` or publish the package first, then add tools via the dashboard.');
  }

  // 3. Find or create a "Sandbox Shell" collection owned by this user
  let collection = await prisma.collection.findFirst({
    where: {
      userId: user.id,
      tools: {
        some: {
          tool: {
            package: { npmPackageName: '@tpmjs/official-sandbox-shell' },
          },
        },
      },
    },
    select: { id: true, slug: true, name: true },
  });

  if (!collection && toolIds.length > 0) {
    collection = await prisma.collection.create({
      data: {
        name: 'Sandbox Shell Tools',
        slug: 'sandbox-shell-tools',
        description:
          'Shell execution, file I/O, and directory listing tools for the TPMJS Agent Sandbox.',
        userId: user.id,
        isPublic: true,
        executorType: 'sandbox',
        executorConfig: { type: 'sandbox' },
        tools: {
          create: toolIds.map((toolId, i) => ({
            toolId,
            position: i,
          })),
        },
      },
      select: { id: true, slug: true, name: true },
    });
    console.log(`Created collection: ${collection.name} (${collection.slug})`);
  } else if (collection) {
    console.log(`Found existing collection: ${collection.name} (${collection.slug})`);
  }

  // 4. Check for existing agent with this name
  const existingAgent = await prisma.agent.findFirst({
    where: { userId: user.id, name: 'Dev Sandbox' },
    select: { id: true, uid: true, name: true },
  });

  if (existingAgent) {
    console.log(`Agent already exists: ${existingAgent.name} (${existingAgent.uid})`);
    console.log(`Dashboard: https://tpmjs.com/dashboard/agents/${existingAgent.id}`);
    console.log(`Chat: https://tpmjs.com/${user.username}/agents/${existingAgent.uid}`);
    return;
  }

  // 5. Create the agent
  const agent = await prisma.agent.create({
    data: {
      uid: 'dev-sandbox',
      name: 'Dev Sandbox',
      description:
        'Development assistant with sandbox access. Clone repos, edit files, run commands, and commit changes.',
      userId: user.id,
      provider: 'ANTHROPIC',
      modelId: 'claude-sonnet-4-20250514',
      systemPrompt: [
        'You are a development assistant with full access to a sandboxed workspace.',
        'You can clone git repos, read and write files, run shell commands, and make git commits.',
        '',
        'When the user asks you to work on a repo:',
        '1. Clone it with `git clone <url> --depth 1`',
        '2. Explore the codebase to understand the structure',
        '3. Make the requested changes',
        '4. Stage and commit with a clear commit message',
        '',
        'Always confirm what you did after completing a task.',
        'Be concise but thorough. Show relevant file contents when helpful.',
        'If you need a GitHub token for private repos, ask the user to set GITHUB_TOKEN in the agent env vars.',
      ].join('\n'),
      temperature: 0.3,
      maxToolCallsPerTurn: 25,
      maxMessagesInContext: 20,
      executorType: 'sandbox',
      executorConfig: { type: 'sandbox' },
      isPublic: false,
      likeCount: 1,
      // Connect collection if we have one
      ...(collection
        ? {
            collections: {
              create: {
                collectionId: collection.id,
                position: 0,
              },
            },
          }
        : {}),
    },
    select: {
      id: true,
      uid: true,
      name: true,
      provider: true,
      modelId: true,
      executorType: true,
    },
  });

  console.log('\n✅ Agent created successfully!');
  console.log(`   Name: ${agent.name}`);
  console.log(`   UID: ${agent.uid}`);
  console.log(`   Provider: ${agent.provider} / ${agent.modelId}`);
  console.log(`   Executor: ${agent.executorType}`);
  console.log(`   ID: ${agent.id}`);
  console.log(`\n📍 Dashboard: https://tpmjs.com/dashboard/agents/${agent.id}`);
  console.log(`💬 Chat: https://tpmjs.com/${user.username}/agents/${agent.uid}`);

  // Auto-like from owner
  await prisma.agentLike
    .create({
      data: { agentId: agent.id, userId: user.id },
    })
    .catch(() => {});

  console.log('\n⚙️  Next steps:');
  console.log('   1. Go to the dashboard and add your ANTHROPIC_API_KEY in the Env Vars tab');
  console.log('   2. Set AGENT_SANDBOX_URL in Vercel env vars (or agent env vars)');
  console.log(
    '   3. Optionally add GITHUB_TOKEN in agent env vars for private repo access'
  );
  console.log('   4. Start chatting! Try: "Clone https://github.com/thomasdavis/omega and list the files"');
}

main()
  .catch((e) => {
    console.error('Error:', e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

