329→function handleGetSession(sessionId: string): Response {
330→  const session = getSession(sessionId);
331→
332→  if (!session) {
333→    return Response.json(
334→      { error: 'Session not found or expired' },
335→      { status: 404, headers: corsHeaders() }
336→    );
337→  }
338→
339→  return Response.json(
340→    {
341→      sessionId: session.sessionId,
342→      workDir: session.workDir,
343→      createdAt: session.createdAt.toISOString(),
344→      expiresAt: session.expiresAt.toISOString(),
345→      toolCallCount: session.toolCallCount,
346→    },
