412→/**
413→ * Execute a tool using the resolved executor configuration
414→ *
415→ * @param config - Resolved executor config (or null for default)
416→ * @param request - Tool execution request
417→ * @param sessionId - Optional session ID for sandbox executors
418→ * @returns Execution result
419→ */
420→export async function executeWithExecutor(
421→  config: ExecutorConfig | null,
422→  request: ExecuteToolRequest,
423→  sessionId?: string
424→): Promise<ExecuteToolResponse> {
425→  const resolvedConfig = config ?? { type: 'default' };
426→
427→  // Use custom URL executor
428→  if (resolvedConfig.type === 'custom_url' && resolvedConfig.url) {
429→    return executeWithCustomUrl(resolvedConfig.url, resolvedConfig.apiKey, request);
430→  }
431→
432→  // Use sandbox executor
433→  if (resolvedConfig.type === 'sandbox' && sessionId) {
434→    const sandboxUrl = resolveSandboxUrl(resolvedConfig);
435→    if (!sandboxUrl) {
436→      return {
437→        success: false,
438→        error:
439→          'Sandbox executor URL not configured. Set AGENT_SANDBOX_URL or provide a custom URL.',
440→        executionTimeMs: 0,
441→      };
442→    }
443→    return executeWithSandbox(sandboxUrl, resolvedConfig.apiKey, request, sessionId);
444→  }
445→
446→  // Default: use existing package-executor (which uses SANDBOX_EXECUTOR_URL)
447→  const result = await executePackage(request.packageName, request.name, request.params, {
448→    env: request.env,
449→    version: request.version,
450→  });
451→
452→  return {
453→    success: result.success,
454→    output: result.output,
455→    error: result.error,
456→    executionTimeMs: result.executionTimeMs,
457→  };
458→}
