  1→/**
  2→ * Test data cleanup utilities
  3→ *
  4→ * Tracks created test data and provides cleanup functions
  5→ * to ensure a clean state after tests complete.
  6→ */
  7→
  8→import { prisma } from '@tpmjs/db';
  9→
 10→/**
 11→ * Tracks created test data IDs for cleanup
 12→ */
 13→export class TestDataTracker {
 14→  private agentIds: Set<string> = new Set();
 15→  private collectionIds: Set<string> = new Set();
 16→  private conversationIds: Set<string> = new Set();
 17→  private apiKeyIds: Set<string> = new Set();
 18→  private tpmjsApiKeyIds: Set<string> = new Set();
 19→
 20→  trackAgent(id: string): void {
 21→    this.agentIds.add(id);
 22→  }
 23→
 24→  trackCollection(id: string): void {
 25→    this.collectionIds.add(id);
 26→  }
 27→
 28→  trackConversation(id: string): void {
 29→    this.conversationIds.add(id);
 30→  }
 31→
 32→  trackApiKey(id: string): void {
 33→    this.apiKeyIds.add(id);
 34→  }
 35→
 36→  trackTpmjsApiKey(id: string): void {
 37→    this.tpmjsApiKeyIds.add(id);
 38→  }
 39→
 40→  getTrackedIds(): {
 41→    agents: string[];
 42→    collections: string[];
 43→    conversations: string[];
 44→    apiKeys: string[];
 45→    tpmjsApiKeys: string[];
 46→  } {
 47→    return {
 48→      agents: Array.from(this.agentIds),
 49→      collections: Array.from(this.collectionIds),
 50→      conversations: Array.from(this.conversationIds),
 51→      apiKeys: Array.from(this.apiKeyIds),
 52→      tpmjsApiKeys: Array.from(this.tpmjsApiKeyIds),
 53→    };
 54→  }
 55→
 56→  /**
 57→   * Clean up all tracked test data
 58→   */
 59→  async cleanup(): Promise<void> {
 60→    const { agents, collections, conversations, apiKeys, tpmjsApiKeys } = this.getTrackedIds();
 61→
 62→    // Delete in order to respect foreign key constraints
 63→    // 1. Conversations (depend on agents)
 64→    if (conversations.length > 0) {
 65→      await prisma.conversation.deleteMany({
 66→        where: { id: { in: conversations } },
 67→      });
 68→    }
 69→
 70→    // 2. Agent tool associations
 71→    if (agents.length > 0) {
 72→      await prisma.agentTool.deleteMany({
 73→        where: { agentId: { in: agents } },
 74→      });
 75→      await prisma.agentCollection.deleteMany({
 76→        where: { agentId: { in: agents } },
 77→      });
 78→    }
 79→
 80→    // 3. Collection tool associations
 81→    if (collections.length > 0) {
 82→      await prisma.collectionTool.deleteMany({
 83→        where: { collectionId: { in: collections } },
 84→      });
 85→    }
 86→
 87→    // 4. Agents
 88→    if (agents.length > 0) {
 89→      await prisma.agent.deleteMany({
 90→        where: { id: { in: agents } },
 91→      });
 92→    }
 93→
 94→    // 5. Collections
 95→    if (collections.length > 0) {
 96→      await prisma.collection.deleteMany({
 97→        where: { id: { in: collections } },
 98→      });
 99→    }
100→
101→    // 6. User API keys
102→    if (apiKeys.length > 0) {
103→      await prisma.userApiKey.deleteMany({
104→        where: { id: { in: apiKeys } },
105→      });
106→    }
107→
108→    // 7. TPMJS API keys
109→    if (tpmjsApiKeys.length > 0) {
110→      await prisma.tpmjsApiKey.deleteMany({
111→        where: { id: { in: tpmjsApiKeys } },
112→      });
113→    }
114→
115→    // Clear tracked IDs
116→    this.agentIds.clear();
117→    this.collectionIds.clear();
118→    this.conversationIds.clear();
119→    this.apiKeyIds.clear();
120→    this.tpmjsApiKeyIds.clear();
121→  }
122→}
