255→export const readFile = tool({
256→  description: 'Read a file from the sandbox workspace.',
257→  inputSchema: jsonSchema<ReadFileInput>({
258→    type: 'object',
259→    properties: {
260→      path: {
261→        type: 'string',
262→        description: 'File path relative to workspace root',
263→      },
264→      _sandboxWorkDir: {
265→        type: 'string',
266→        description: 'Injected by sandbox server — workspace directory',
267→      },
268→    },
269→    required: ['path'],
270→    additionalProperties: false,
271→  }),
272→  async execute({ path: filePath, _sandboxWorkDir }) {
273→    if (!_sandboxWorkDir) {
274→      throw new Error('readFile requires a sandbox session (_sandboxWorkDir not set)');
275→    }
276→
277→    const resolved = resolveSandboxPath(_sandboxWorkDir, filePath);
278→
279→    // Symlink escape check: verify the real (canonical) path is still in workspace
280→    try {
281→      const realPath = await Deno.realPath(resolved);
282→      const normalizedWorkDir = '/' + _sandboxWorkDir.replace(/^\/+/, '').replace(/\/+$/, '');
283→      if (!realPath.startsWith(normalizedWorkDir)) {
284→        throw new Error(`Path escapes sandbox workspace via symlink: ${filePath}`);
285→      }
286→    } catch (error) {
287→      // Re-throw our own escape error
288→      if (error instanceof Error && error.message.includes('escapes sandbox')) {
289→        throw error;
290→      }
291→      // NotFound is fine — stat will fail with a better error below
292→    }
293→
294→    const content = await Deno.readTextFile(resolved);
295→
296→    const { text, truncated } = truncate(content, MAX_READ_SIZE);
297→
298→    const stat = await Deno.stat(resolved);
299→
300→    const result: ReadFileResult = {
301→      content: text,
302→      path: filePath,
303→      size: stat.size,
304→      truncated,
305→    };
306→
307→    return result;
308→  },
309→});
