194→// Sandbox Session Management
195→// =============================================================================
196→
197→/**
198→ * Resolve sandbox URL from config or environment variable
199→ */
200→export function resolveSandboxUrl(config: SandboxExecutorConfig): string | null {
201→  return config.url || process.env.AGENT_SANDBOX_URL || null;
202→}
203→
204→/**
205→ * Create or resume a sandbox session (idempotent)
206→ * If the session already exists, extends its TTL and returns it.
207→ */
208→export async function createSandboxSession(
209→  url: string,
210→  apiKey: string | undefined,
211→  sessionId: string,
212→  timeoutSeconds?: number
213→): Promise<CreateSessionResponse> {
214→  return withRetry(
215→    async () => {
216→      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
217→      if (apiKey) {
218→        headers.Authorization = `Bearer ${apiKey}`;
219→      }
220→
221→      const controller = new AbortController();
222→      const timeoutId = setTimeout(() => controller.abort(), 15000);
223→
224→      try {
225→        const response = await fetch(`${url}/sessions`, {
226→          method: 'POST',
227→          headers,
228→          body: JSON.stringify({ sessionId, timeoutSeconds }),
229→          signal: controller.signal,
230→        });
231→
232→        clearTimeout(timeoutId);
233→
234→        if (response.status === 429) {
235→          throw new Error('Sandbox at capacity (429). Retrying...');
236→        }
237→
238→        if (!response.ok) {
239→          const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
240→            error?: string;
241→          };
242→          throw new Error(
243→            errorData.error || `Failed to create sandbox session: ${response.status}`
244→          );
245→        }
246→
247→        return (await response.json()) as CreateSessionResponse;
248→      } catch (error) {
249→        clearTimeout(timeoutId);
250→        if (error instanceof Error && error.name === 'AbortError') {
251→          throw new Error('Sandbox session creation timed out');
252→        }
253→        throw error;
254→      }
255→    },
256→    {
257→      shouldRetry: (error) => {
258→        const msg = error instanceof Error ? error.message : String(error);
259→        // Retry on network errors, timeouts, and capacity issues
260→        return (
261→          msg.includes('timed out') ||
262→          msg.includes('429') ||
263→          msg.includes('ECONNREFUSED') ||
264→          msg.includes('fetch failed')
265→        );
266→      },
267→    }
268→  );
269→}
270→
271→/**
272→ * Destroy a sandbox session (fire-and-forget safe)
273→ * Returns gracefully even if the session doesn't exist.
274→ */
275→export async function destroySandboxSession(
276→  url: string,
277→  apiKey: string | undefined,
278→  sessionId: string
279→): Promise<DestroySessionResponse> {
280→  const headers: Record<string, string> = {};
281→  if (apiKey) {
282→    headers.Authorization = `Bearer ${apiKey}`;
283→  }
284→
285→  try {
286→    const controller = new AbortController();
287→    const timeoutId = setTimeout(() => controller.abort(), 10000);
288→
289→    const response = await fetch(`${url}/sessions/${encodeURIComponent(sessionId)}`, {
290→      method: 'DELETE',
291→      headers,
292→      signal: controller.signal,
293→    });
294→
295→    clearTimeout(timeoutId);
296→
297→    if (!response.ok && response.status !== 404) {
298→      return { sessionId, destroyed: false };
299→    }
300→
301→    return (await response
302→      .json()
303→      .catch(() => ({ sessionId, destroyed: true }))) as DestroySessionResponse;
304→  } catch {
305→    // Fire-and-forget: don't throw on cleanup failures
306→    return { sessionId, destroyed: false };
307→  }
308→}
