523→ */
524→export async function testExecutor(
525→  url: string,
526→  apiKey?: string
527→): Promise<{ success: boolean; executionTimeMs: number; error?: string }> {
528→  const testRequest: ExecuteToolRequest = {
529→    packageName: '@tpmjs/hello',
530→    name: 'helloWorldTool',
531→    version: '0.0.2',
532→    params: { includeTimestamp: true },
533→  };
534→
535→  const result = await executeWithCustomUrl(url, apiKey, testRequest, 30000); // 30 second timeout for test (includes npm install)
536→
537→  return {
538→    success: result.success,
539→    executionTimeMs: result.executionTimeMs,
540→    error: result.error,
541→  };
542→}
