312→ */
313→async function executeWithSandbox(
314→  url: string,
315→  apiKey: string | undefined,
316→  request: ExecuteToolRequest,
317→  sessionId: string,
318→  timeout: number = DEFAULT_TIMEOUT
319→): Promise<ExecuteToolResponse> {
320→  const startTime = Date.now();
321→
322→  const headers: Record<string, string> = {
323→    'Content-Type': 'application/json',
324→  };
325→
326→  if (apiKey) {
327→    headers.Authorization = `Bearer ${apiKey}`;
328→  }
329→
330→  // Retry on transient failures (network errors, 429, 502, 503)
331→  let lastError: unknown;
332→  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
333→    try {
334→      const controller = new AbortController();
335→      const timeoutId = setTimeout(() => controller.abort(), timeout);
336→
337→      const response = await fetch(`${url}/execute-tool`, {
338→        method: 'POST',
339→        headers,
340→        body: JSON.stringify({ ...request, sessionId }),
341→        signal: controller.signal,
342→      });
343→
344→      clearTimeout(timeoutId);
345→
346→      const executionTimeMs = Date.now() - startTime;
347→
348→      // Retry on 429 (capacity) or 502/503 (transient server issues)
349→      if ((response.status === 429 || response.status === 502 || response.status === 503) && attempt < MAX_RETRIES) {
350→        const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
351→        console.warn(`[Sandbox] Got ${response.status}, retrying in ${delay}ms (attempt ${attempt + 1})`);
352→        await new Promise((resolve) => setTimeout(resolve, delay));
353→        continue;
354→      }
355→
356→      if (!response.ok) {
357→        const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
358→          error?: string;
359→        };
360→        return {
361→          success: false,
362→          error: errorData.error || `Sandbox executor error: ${response.status}`,
363→          executionTimeMs,
364→        };
365→      }
366→
367→      const result = (await response.json()) as ExecuteToolResponse;
368→
369→      return {
370→        success: result.success,
371→        output: result.output,
372→        error: result.error,
373→        executionTimeMs: result.executionTimeMs || executionTimeMs,
374→      };
375→    } catch (error) {
376→      lastError = error;
377→
378→      if (error instanceof Error && error.name === 'AbortError') {
379→        return {
380→          success: false,
381→          error: 'Execution timeout',
382→          executionTimeMs: Date.now() - startTime,
383→        };
384→      }
385→
386→      // Retry on network errors
387→      if (attempt < MAX_RETRIES) {
388→        const msg = error instanceof Error ? error.message : String(error);
389→        if (msg.includes('ECONNREFUSED') || msg.includes('fetch failed') || msg.includes('ECONNRESET')) {
390→          const delay = RETRY_BASE_DELAY_MS * 2 ** attempt;
391→          console.warn(`[Sandbox] Network error, retrying in ${delay}ms (attempt ${attempt + 1}):`, msg);
392→          await new Promise((resolve) => setTimeout(resolve, delay));
393→          continue;
394→        }
395→      }
396→
397→      return {
398→        success: false,
399→        error: error instanceof Error ? error.message : String(error),
400→        executionTimeMs: Date.now() - startTime,
401→      };
402→    }
403→  }
404→
405→  return {
406→    success: false,
407→    error: lastError instanceof Error ? lastError.message : String(lastError),
408→    executionTimeMs: Date.now() - startTime,
409→  };
410→}
