577→  }
578→
579→  // Test execution (only if health check passed)
580→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
581→  if (healthResult.healthy) {
582→    const execResult = await testExecutor(url, apiKey);
583→    testResult = {
584→      success: execResult.success,
585→      executionTimeMs: execResult.executionTimeMs,
586→    };
587→    if (!execResult.success) {
588→      errors.push(execResult.error || 'Test execution failed');
589→    }
590→  }
591→
592→  return {
593→    valid: errors.length === 0,
594→    healthCheck: {
595→      healthy: healthResult.healthy,
596→      response: healthResult.response,
597→    },
598→    testExecution: testResult,
599→    errors,
600→  };
