436→      for (const msg of toolMessages) {
437→        expect(msg.toolCallId).toBeDefined();
438→        expect(msg.toolName).toBeDefined();
439→        expect(msg.toolResult).toBeDefined();
440→      }
441→    });
442→  });
443→
444→  describe('Agent with username/uid lookup', () => {
445→    it('should accept agent with username/uid format', async () => {
446→      if (!serverAvailable || !testAgent) {
447→        console.log('Skipping: Server not available or no test agent');
448→        return;
449→      }
450→
451→      const response = await fetch(
452→        `${BASE_URL}/api/${testAgent.user.username}/agents/${testAgent.uid}/conversations`,
453→        {
454→          method: 'GET',
455→        }
456→      );
457→
458→      expect(response.ok).toBe(true);
459→      const result = await response.json();
460→      expect(result.success).toBe(true);
461→    });
462→  });
463→});
