219→  it('should retrieve conversation history with tool calls', async () => {
220→    if (!testAgent || !collectionId) {
221→      console.log('Skipping: No test agent or collection available');
222→      return;
223→    }
224→
225→    // Retrieve the conversation we just had
226→    const result = await ctx.apiKeyClient.get<{
227→      success: boolean;
228→      data: {
229→        id: string;
230→        slug: string;
231→        messages: Array<{
232→          role: string;
